import React, { useState, useEffect } from 'react';
import { useApp } from '../context/AppContext';
import { PRESET_COLORS, DEFAULT_HEIGHT } from '../constants';
import { Trash2, BoxSelect, Copy, Move, Maximize, Grid3X3, ArrowRight, ArrowDown } from 'lucide-react';
import * as THREE from 'three';
import { IPoint } from '../types';

// Helper to determine local bounding box from points
const getRawDimensions = (points: IPoint[]) => {
  if (points.length === 0) return { width: 0, depth: 0 };
  let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity;
  points.forEach(p => {
    minX = Math.min(minX, p.x);
    maxX = Math.max(maxX, p.x);
    minZ = Math.min(minZ, p.z);
    maxZ = Math.max(maxZ, p.z);
  });
  return { 
    width: maxX - minX || 0.1, 
    depth: maxZ - minZ || 0.1 
  };
};

// Anchor types: -1 (Left/Top), 0 (Center), 1 (Right/Bottom)
type AnchorX = -1 | 0 | 1;
type AnchorZ = -1 | 0 | 1;

const PropertiesPanel: React.FC = () => {
  const { selectedId, shapes, updateShape, removeShape, copyShape, formatValue, transformMode, setTransformMode, unit } = useApp();

  // Local state for Anchor (-1, 0, 1)
  const [anchor, setAnchor] = useState<{x: AnchorX, z: AnchorZ}>({ x: 0, z: 0 });

  // Reset anchor when selection changes
  useEffect(() => {
    setAnchor({ x: 0, z: 0 });
  }, [selectedId]);

  if (!selectedId) {
    return (
      <div className="absolute top-4 right-4 w-64 p-4 bg-slate-800/90 backdrop-blur-sm rounded-xl border border-slate-700 shadow-xl z-10 text-slate-400 text-sm flex flex-col items-center justify-center min-h-[100px]">
        <BoxSelect className="mb-2 opacity-50" size={32} />
        <p>請選取物件以編輯</p>
      </div>
    );
  }

  const selectedShape = shapes.find(s => s.id === selectedId);
  if (!selectedShape) return null;

  // Calculate current real-world dimensions
  const rawDims = getRawDimensions(selectedShape.points);
  const currentWidth = rawDims.width * selectedShape.scale[0];
  const currentDepth = rawDims.depth * selectedShape.scale[2];

  // Logic to update size with anchor compensation
  const handleDimensionChange = (newVal: number, type: 'width' | 'depth') => {
    if (isNaN(newVal) || newVal <= 0) return;

    // 1. Calculate Scale Factor and Delta
    const oldSize = type === 'width' ? currentWidth : currentDepth;
    const baseSize = type === 'width' ? rawDims.width : rawDims.depth;

    // Protect against zero division
    if (baseSize < 0.001) return;

    const newScaleVal = newVal / baseSize;
    const sizeDiff = newVal - oldSize;

    // 2. Determine Axis of Expansion in Local Space
    // If Anchor is -1 (Left), we expand to +X (Right). Center moves +diff/2.
    // If Anchor is 1 (Right), we expand to -X (Left). Center moves -diff/2.
    // If Anchor is 0 (Center), Center moves 0.

    // Note: The logic below assumes the shape geometry is centered at (0,0) locally.
    // The visual effect of "Holding Left Edge" means the center must move Right.
    let shiftX = 0;
    let shiftZ = 0;

    if (type === 'width') {
       // anchor.x: -1 (Left), 0 (Center), 1 (Right)
       // If anchored Left (-1), we grow Right (+). Center moves +diff/2.
       // If anchored Right (1), we grow Left (-). Center moves -diff/2.
       // Formula: shift = (diff / 2) * (-anchor)
       shiftX = (sizeDiff / 2) * (-anchor.x);
    } else {
       // Same logic for Depth (Z)
       // anchor.z: -1 (Top/Back), 0 (Center), 1 (Bottom/Front)
       shiftZ = (sizeDiff / 2) * (-anchor.z);
    }

    // 3. Rotate the Shift Vector to World Space
    const shiftVector = new THREE.Vector3(shiftX, 0, shiftZ);
    const rotationEuler = new THREE.Euler(0, -selectedShape.rotation, 0); // Note: ThreeJS Y-rotation direction might be inverted relative to our storage
    // Actually, our stored rotation is Y axis. Let's strictly use standard rotation.
    // In DrawingManager we used: rotation = -Math.atan2(dz, dx);
    // In RenderedShape we used: rotation={[-Math.PI / 2, 0, shape.rotation]}
    // Let's use standard trig to be safe.

    const cos = Math.cos(selectedShape.rotation);
    const sin = Math.sin(selectedShape.rotation);

    // Rotate (x, z) 
    // x' = x cos - z sin
    // z' = x sin + z cos
    const worldShiftX = shiftVector.x * cos - shiftVector.z * sin;
    const worldShiftZ = shiftVector.x * sin + shiftVector.z * cos;

    // 4. Update Shape
    const newScale = [...selectedShape.scale] as [number, number, number];
    if (type === 'width') newScale[0] = newScaleVal;
    if (type === 'depth') newScale[2] = newScaleVal;

    updateShape(selectedShape.id, {
      scale: newScale,
      position: [
        selectedShape.position[0] + worldShiftX,
        selectedShape.position[1],
        selectedShape.position[2] + worldShiftZ
      ]
    });
  };

  const getUnitVal = (val: number) => unit === 'cm' ? parseFloat((val * 100).toFixed(1)) : parseFloat(val.toFixed(3));
  const setUnitVal = (val: number) => unit === 'cm' ? val / 100 : val;

  return (
    <div className="absolute top-4 right-4 w-72 bg-slate-800/90 backdrop-blur-sm rounded-xl border border-slate-700 shadow-xl z-10 flex flex-col overflow-hidden max-h-[90vh] overflow-y-auto">
      <div className="p-4 border-b border-slate-700 bg-slate-900/50 flex justify-between items-center sticky top-0 z-20">
        <h3 className="text-white font-semibold flex items-center gap-2">
          <span className="w-2 h-6 bg-blue-500 rounded-full"/>
          屬性
        </h3>
        <div className="flex gap-1">
          <button 
            onClick={() => copyShape(selectedId)}
            className="text-indigo-400 hover:text-indigo-300 p-1.5 hover:bg-indigo-500/10 rounded transition-colors"
            title="複製物件"
          >
            <Copy size={18} />
          </button>
          <button 
            onClick={() => removeShape(selectedId)}
            className="text-red-400 hover:text-red-300 p-1.5 hover:bg-red-500/10 rounded transition-colors"
            title="刪除物件"
          >
            <Trash2 size={18} />
          </button>
        </div>
      </div>

      <div className="p-4 space-y-6">

        {/* Name */}
        <div className="space-y-2">
            <label className="text-xs text-slate-400 font-medium uppercase tracking-wider">名稱</label>
            <input 
                type="text" 
                value={selectedShape.name} 
                onChange={(e) => updateShape(selectedId, { name: e.target.value })}
                className="w-full bg-slate-900 border border-slate-600 rounded px-3 py-2 text-white text-sm focus:border-blue-500 focus:outline-none"
            />
        </div>

        {/* Transform Mode Toggle */}
        <div className="space-y-2">
            <label className="text-xs text-slate-400 font-medium uppercase tracking-wider">操作模式</label>
            <div className="flex bg-slate-900 rounded p-1">
                <button 
                    onClick={() => setTransformMode('translate')}
                    className={`flex-1 flex items-center justify-center gap-2 text-xs py-1.5 rounded transition-colors ${transformMode === 'translate' ? 'bg-blue-600 text-white' : 'text-slate-500 hover:text-slate-300'}`}
                >
                    <Move size={14} /> 移動
                </button>
                <button 
                    onClick={() => setTransformMode('scale')}
                    className={`flex-1 flex items-center justify-center gap-2 text-xs py-1.5 rounded transition-colors ${transformMode === 'scale' ? 'bg-blue-600 text-white' : 'text-slate-500 hover:text-slate-300'}`}
                >
                    <Maximize size={14} /> 縮放 (厚/長)
                </button>
            </div>
        </div>

        {/* --- Dimensions & Anchor Section --- */}
        <div className="space-y-3 pt-2 border-t border-slate-700/50">
           <div className="flex justify-between items-center mb-1">
              <label className="text-xs text-slate-400 font-medium uppercase tracking-wider flex items-center gap-1">
                 尺寸調整 <Grid3X3 size={12}/>
              </label>
              <span className="text-[10px] text-slate-500">選擇錨點以鎖定方向</span>
           </div>

           <div className="flex gap-4">
              {/* Anchor Grid */}
              <div className="grid grid-cols-3 gap-1 bg-slate-900 p-1 rounded border border-slate-700 w-[68px] h-[68px] flex-shrink-0">
                  {[-1, 0, 1].flatMap((z) => 
                     [-1, 0, 1].map((x) => (
                        <button
                           key={`${x}-${z}`}
                           onClick={() => setAnchor({ x: x as AnchorX, z: z as AnchorZ })}
                           className={`rounded-sm transition-all duration-200 ${
                              anchor.x === x && anchor.z === z 
                                ? 'bg-blue-500 scale-110 shadow-lg shadow-blue-500/50' 
                                : 'bg-slate-700 hover:bg-slate-600'
                           }`}
                        />
                     ))
                  )}
              </div>

              {/* Inputs */}
              <div className="flex-1 space-y-2">
                 <div className="flex items-center gap-2">
                    <div className="w-5 text-center text-slate-500 font-mono text-xs">W</div>
                    <input 
                      type="number"
                      step={unit === 'm' ? 0.1 : 10}
                      value={getUnitVal(currentWidth)}
                      onChange={(e) => handleDimensionChange(setUnitVal(parseFloat(e.target.value)), 'width')}
                      className="flex-1 bg-slate-900 border border-slate-600 rounded px-2 py-1 text-white text-xs font-mono focus:border-blue-500 outline-none"
                    />
                 </div>
                 <div className="flex items-center gap-2">
                    <div className="w-5 text-center text-slate-500 font-mono text-xs">D</div>
                    <input 
                      type="number"
                      step={unit === 'm' ? 0.1 : 10}
                      value={getUnitVal(currentDepth)}
                      onChange={(e) => handleDimensionChange(setUnitVal(parseFloat(e.target.value)), 'depth')}
                      className="flex-1 bg-slate-900 border border-slate-600 rounded px-2 py-1 text-white text-xs font-mono focus:border-blue-500 outline-none"
                    />
                 </div>
              </div>
           </div>

           {/* Helper text for current anchor */}
           <div className="text-[10px] text-slate-500 text-right">
              鎖定: {
                anchor.x === -1 ? '左' : anchor.x === 1 ? '右' : '中'
              } / {
                anchor.z === -1 ? '上' : anchor.z === 1 ? '下' : '中'
              }
           </div>
        </div>

        {/* Height Slider */}
        <div className="space-y-3 pt-2 border-t border-slate-700/50">
          <div className="flex justify-between items-center">
             <label className="text-xs text-slate-400 font-medium uppercase tracking-wider">高度 (推拉)</label>
             <span className="text-blue-400 font-mono text-sm">{formatValue(selectedShape.height)}</span>
          </div>
          <input
            type="range"
            min="0.05"
            max="10"
            step="0.05"
            value={selectedShape.height}
            onChange={(e) => updateShape(selectedId, { height: parseFloat(e.target.value) })}
            className="w-full h-2 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-blue-500"
          />
        </div>

