          <div className="flex justify-between items-center">
             <label className="text-xs text-slate-400 font-medium uppercase tracking-wider">旋轉</label>
             <span className="text-blue-400 font-mono text-sm">{((selectedShape.rotation * 180) / Math.PI).toFixed(0)}°</span>
          </div>
          <input
