            min="0"
            max={Math.PI * 2}
            step="0.1"
            value={selectedShape.rotation}
            onChange={(e) => updateShape(selectedId, { rotation: parseFloat(e.target.value) })}
            className="w-full h-2 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-blue-500"
          />
