          <div className="flex justify-between items-center">
             <label className="text-xs text-slate-400 font-medium uppercase tracking-wider">旋轉</label>
             <span className="text-blue-400 font-mono text-sm">{((selectedShape.rotation * 180) / Math.PI).toFixed(0)}°</span>
          </div>
          <input
            type="range"
            min="0"
            max={Math.PI * 2}
            step="0.1"
            value={selectedShape.rotation}
            onChange={(e) => updateShape(selectedId, { rotation: parseFloat(e.target.value) })}
            className="w-full h-2 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-blue-500"
          />
        </div>
        )}

        {/* Color Picker */}
        <div className="space-y-2">
          <label className="text-xs text-slate-400 font-medium uppercase tracking-wider">材質顏色</label>
          <div className="grid grid-cols-4 gap-2">
            {PRESET_COLORS.map(color => (
              <button
                key={color}
                onClick={() => updateShape(selectedId, { color })}
                className={`w-full aspect-square rounded-md border-2 transition-transform hover:scale-105 ${selectedShape.color === color ? 'border-white ring-2 ring-blue-500/50' : 'border-transparent'}`}
                style={{ backgroundColor: color }}
              />
            ))}
            <div className="relative w-full aspect-square rounded-md overflow-hidden bg-gradient-to-br from-white to-black border-2 border-slate-600">
                <input 
                    type="color" 
                    className="absolute inset-0 w-[150%] h-[150%] -top-1/4 -left-1/4 cursor-pointer opacity-0" 
                    value={selectedShape.color}
                    onChange={(e) => updateShape(selectedId, { color: e.target.value })}
                />
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

