import React, { useRef, useState, useMemo, useEffect } from 'react';
import { Canvas, useThree, ThreeEvent, useFrame } from '@react-three/fiber';
import { OrbitControls, Grid, Environment, TransformControls, Html, Line, GizmoHelper, GizmoViewport } from '@react-three/drei';
import * as THREE from 'three';
import { useApp } from '../context/AppContext';
import { ToolType, IPoint, IShape, ShapeType } from '../types';
import { SNAP_GRID, DEFAULT_COLOR, FLAT_COLOR, HIGHLIGHT_COLOR, DIMENSION_COLOR, DEFAULT_HEIGHT } from '../constants';

// --- Types for Snapping ---
interface SnapPoint {
    pos: THREE.Vector3;
    type: 'vertex' | 'center' | 'midpoint';
}

// --- Helpers ---

// Convert 2D points to Three Shape
const createThreeShape = (points: IPoint[]) => {
  const shape = new THREE.Shape();
  if (!points || points.length === 0) return shape;

  if (points[0]) {
    shape.moveTo(points[0].x, points[0].z);
    for (let i = 1; i < points.length; i++) {
        if (points[i]) {
            shape.lineTo(points[i].x, points[i].z);
        }
    }
  }
  shape.closePath();
  return shape;
};

// Generate points for a circle
const createCirclePoints = (radius: number, segments = 32): IPoint[] => {
  const points: IPoint[] = [];
  for (let i = 0; i < segments; i++) {
    const theta = (i / segments) * Math.PI * 2;
    points.push({ x: Math.cos(theta) * radius, y: 0, z: Math.sin(theta) * radius });
  }
  points.push(points[0]);
  return points;
};

// Generate points for a quarter arc
const createArcPoints = (radius: number, segments = 16): IPoint[] => {
  const points: IPoint[] = [];
  points.push({ x: 0, y: 0, z: 0 });
  for (let i = 0; i <= segments; i++) {
    const theta = (i / segments) * (Math.PI / 2); // 90 degrees
    points.push({ x: Math.cos(theta) * radius, y: 0, z: Math.sin(theta) * radius });
  }
  points.push({ x: 0, y: 0, z: 0 });
  return points;
};

// Calculate all snap candidates for a shape (Vertices, Midpoints, Centers - Top & Bottom)
const getSnapCandidates = (shape: IShape): SnapPoint[] => {
    // Dimensions don't offer snap points to avoid clutter
    if (shape.type === 'dimension') return [];

    const candidates: SnapPoint[] = [];
    const mat = new THREE.Matrix4();
    const quaternion = new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(0, 1, 0), shape.rotation);
    const scale = new THREE.Vector3(shape.scale[0], shape.scale[1], shape.scale[2]);
    const position = new THREE.Vector3(shape.position[0], shape.position[1], shape.position[2]);

    mat.compose(position, quaternion, scale);

    // 1. Center (Bottom & Top)
    // Calculate centroid of the base polygon
    let cx = 0, cz = 0;
    if (shape.points && shape.points.length > 0) {
        shape.points.forEach(p => { cx += p.x; cz += p.z; });
        cx /= shape.points.length;
        cz /= shape.points.length;
    }

    const localCenterBottom = new THREE.Vector3(cx, 0, cz);
    const localCenterTop = new THREE.Vector3(cx, shape.height, cz);

    candidates.push({ pos: localCenterBottom.applyMatrix4(mat).clone(), type: 'center' });
    candidates.push({ pos: localCenterTop.applyMatrix4(mat).clone(), type: 'center' });

    // 2. Vertices & Midpoints
    if (shape.points) {
        for (let i = 0; i < shape.points.length; i++) {
            const p = shape.points[i];
            const nextP = shape.points[(i + 1) % shape.points.length];

            // Vertices (Bottom & Top)
            const vBottom = new THREE.Vector3(p.x, 0, p.z);
            const vTop = new THREE.Vector3(p.x, shape.height, p.z);

            candidates.push({ pos: vBottom.clone().applyMatrix4(mat), type: 'vertex' });
            candidates.push({ pos: vTop.clone().applyMatrix4(mat), type: 'vertex' });

            // Midpoints (Bottom & Top)
            const midX = (p.x + nextP.x) / 2;
            const midZ = (p.z + nextP.z) / 2;

            const mBottom = new THREE.Vector3(midX, 0, midZ);
            const mTop = new THREE.Vector3(midX, shape.height, midZ);

            candidates.push({ pos: mBottom.clone().applyMatrix4(mat), type: 'midpoint' });
            candidates.push({ pos: mTop.clone().applyMatrix4(mat), type: 'midpoint' });
        }
    }

    return candidates;
};

// Calculate base dimensions (width/depth) from points
const getBaseDimensions = (points: IPoint[]) => {
    if (!points || points.length === 0) return { width: 0, depth: 0 };
    let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity;
    points.forEach(p => {
        minX = Math.min(minX, p.x);
        maxX = Math.max(maxX, p.x);
        minZ = Math.min(minZ, p.z);
        maxZ = Math.max(maxZ, p.z);
    });
    return { 
        width: maxX - minX || 0.1, 
        depth: maxZ - minZ || 0.1,
        minX, maxX, minZ, maxZ
    };
};

// --- Components ---

const CursorTooltip: React.FC<{ text: string; position: THREE.Vector3 | [number, number, number] }> = ({ text, position }) => {
  const pos = Array.isArray(position) ? position : [position.x, 0.5, position.z];
