import React from 'react';
import { useApp } from '../context/AppContext';
import { PRESET_COLORS } from '../constants';
import { Trash2, BoxSelect, Copy, Maximize } from 'lucide-react';
import { IPoint } from '../types';

// Helper to determine local bounding box from points
const getRawDimensions = (points: IPoint[]) => {
  if (points.length === 0) return { width: 0, depth: 0 };
  let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity;
  points.forEach(p => {
    minX = Math.min(minX, p.x);
    maxX = Math.max(maxX, p.x);
    minZ = Math.min(minZ, p.z);
    maxZ = Math.max(maxZ, p.z);
  });
  return { 
    width: maxX - minX || 0.1, 
    depth: maxZ - minZ || 0.1 
  };
};

const PropertiesPanel: React.FC = () => {
  const { selectedId, shapes, updateShape, removeShape, copyShape, formatValue, unit } = useApp();

  if (!selectedId) {
    return (
      <div className="absolute top-4 right-4 w-64 p-4 bg-slate-800/90 backdrop-blur-sm rounded-xl border border-slate-700 shadow-xl z-10 text-slate-400 text-sm flex flex-col items-center justify-center min-h-[100px]">
        <BoxSelect className="mb-2 opacity-50" size={32} />
        <p>請選取物件以編輯</p>
      </div>
    );
  }

  const selectedShape = shapes.find(s => s.id === selectedId);
  if (!selectedShape) return null;

  const isDimension = selectedShape.type === 'dimension';

  // Calculate current real-world dimensions
  const rawDims = getRawDimensions(selectedShape.points);
  const currentWidth = rawDims.width * selectedShape.scale[0];
  const currentDepth = rawDims.depth * selectedShape.scale[2];

  // Simple numeric updates (Standard center-based scaling for manual input)
  // If user wants specific side, they use the Viewport gizmos.
  const handleDimensionChange = (newVal: number, type: 'width' | 'depth') => {
    if (isNaN(newVal) || newVal <= 0) return;
    const baseSize = type === 'width' ? rawDims.width : rawDims.depth;
    if (baseSize < 0.001) return;
    const newScaleVal = newVal / baseSize;

    const newScale = [...selectedShape.scale] as [number, number, number];
    if (type === 'width') newScale[0] = newScaleVal;
    if (type === 'depth') newScale[2] = newScaleVal;

    updateShape(selectedShape.id, { scale: newScale });
  };

  const getUnitVal = (val: number) => unit === 'cm' ? parseFloat((val * 100).toFixed(1)) : parseFloat(val.toFixed(3));
  const setUnitVal = (val: number) => unit === 'cm' ? val / 100 : val;

  return (
    <div className="absolute top-4 right-4 w-72 bg-slate-800/90 backdrop-blur-sm rounded-xl border border-slate-700 shadow-xl z-10 flex flex-col overflow-hidden max-h-[90vh] overflow-y-auto">
      <div className="p-4 border-b border-slate-700 bg-slate-900/50 flex justify-between items-center sticky top-0 z-20">
        <h3 className="text-white font-semibold flex items-center gap-2">
          <span className={`w-2 h-6 rounded-full ${isDimension ? 'bg-yellow-500' : 'bg-blue-500'}`}/>
          {isDimension ? '尺寸標註' : '屬性'}
        </h3>
        <div className="flex gap-1">
          <button 
            onClick={() => copyShape(selectedId)}
            className="text-indigo-400 hover:text-indigo-300 p-1.5 hover:bg-indigo-500/10 rounded transition-colors"
            title="複製物件"
          >
            <Copy size={18} />
          </button>
          <button 
            onClick={() => removeShape(selectedId)}
            className="text-red-400 hover:text-red-300 p-1.5 hover:bg-red-500/10 rounded transition-colors"
            title="刪除物件"
          >
            <Trash2 size={18} />
          </button>
        </div>
      </div>

      <div className="p-4 space-y-6">

        {/* Name */}
        <div className="space-y-2">
            <label className="text-xs text-slate-400 font-medium uppercase tracking-wider">名稱</label>
            <input 
                type="text" 
                value={selectedShape.name} 
                onChange={(e) => updateShape(selectedId, { name: e.target.value })}
                className="w-full bg-slate-900 border border-slate-600 rounded px-3 py-2 text-white text-sm focus:border-blue-500 focus:outline-none"
            />
        </div>

        {/* --- Dimensions Section --- */}
        {!isDimension && (
