              <button
                key={color}
                onClick={() => updateShape(selectedId, { color })}
                className={`w-full aspect-square rounded-md border-2 transition-transform hover:scale-105 ${selectedShape.color === color ? 'border-white ring-2 ring-blue-500/50' : 'border-transparent'}`}
                style={{ backgroundColor: color }}
              />
            ))}
            <div className="relative w-full aspect-square rounded-md overflow-hidden bg-gradient-to-br from-white to-black border-2 border-slate-600">
                <input 
                    type="color" 
                    className="absolute inset-0 w-[150%] h-[150%] -top-1/4 -left-1/4 cursor-pointer opacity-0" 
                    value={selectedShape.color}
                    onChange={(e) => updateShape(selectedId, { color: e.target.value })}
                />
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

