};

// New Component: Resize Handle Gizmo
interface ResizeHandleProps {
  position: [number, number, number];
  parentScale: [number, number, number];
  axis: 'x' | 'z';
  direction: 1 | -1;
  onDragStart: (e: ThreeEvent<PointerEvent>, axis: 'x' | 'z', direction: 1 | -1) => void;
  color: string;
}

const ResizeHandle: React.FC<ResizeHandleProps> = ({ position, parentScale, axis, direction, onDragStart, color }) => {
  const [hovered, setHovered] = useState(false);

  // Inverse scale to keep handle size constant (e.g. 0.4 units in world space)
  const scaleX = 1 / Math.max(0.001, parentScale[0]);
  const scaleY = 1 / Math.max(0.001, parentScale[1]);
  const scaleZ = 1 / Math.max(0.001, parentScale[2]);

  return (
    <mesh
      position={position}
      scale={[scaleX, scaleY, scaleZ]}
      onPointerOver={() => setHovered(true)}
      onPointerOut={() => setHovered(false)}
      onPointerDown={(e) => {
        e.stopPropagation();
        onDragStart(e, axis, direction);
      }}
      renderOrder={999} // Always render on top
    >
      <boxGeometry args={[0.4, 0.4, 0.4]} />
      <meshBasicMaterial 
        color={hovered ? 'white' : color} 
        depthTest={false}
        transparent
        opacity={1}
      />
      {/* Outline for visibility */}
      <lineSegments>
        <edgesGeometry args={[new THREE.BoxGeometry(0.4, 0.4, 0.4)]} />
        <lineBasicMaterial color="black" depthTest={false} opacity={0.5} transparent />
      </lineSegments>
    </mesh>
  );
};

const DrawingManager: React.FC = () => {
  // ... (No changes needed in DrawingManager logic, it's mostly 2D points handling)
  const { tool, addShape, formatValue } = useApp();
  const [startPoint, setStartPoint] = useState<IPoint | null>(null);
  const [currentPoint, setCurrentPoint] = useState<IPoint | null>(null);
  const [polyPoints, setPolyPoints] = useState<IPoint[]>([]);

  // Measure Tool State
  const [measureStart, setMeasureStart] = useState<IPoint | null>(null);
  const [measureEnd, setMeasureEnd] = useState<IPoint | null>(null);

  const { raycaster, scene, camera } = useThree();

  useEffect(() => {
    setStartPoint(null);
    setCurrentPoint(null);
    setPolyPoints([]);
    setMeasureStart(null);
    setMeasureEnd(null);
  }, [tool]);

  useFrame(({ pointer }) => {
    if (tool === ToolType.SELECT) {
        if (currentPoint) setCurrentPoint(null);
        return;
    }

    raycaster.setFromCamera(pointer, camera);

    const interactables = scene.children.filter(obj => 
        obj.name === 'ground_plane' || 
        obj.userData?.isShape
    );

    const intersects = raycaster.intersectObjects(interactables, true);

    let hitPoint: THREE.Vector3 | null = null;

    for (const hit of intersects) {
        if (hit.object.name === 'cursor_helper' || hit.object.name === 'preview_helper') continue;
        if (hit.object.name === 'ground_plane') {
            hitPoint = hit.point;
            break;
        }
        let obj: THREE.Object3D | null = hit.object;
        let isShape = false;
        while(obj) {
            if (obj.userData?.isShape) {
                isShape = true;
                break;
            }
            obj = obj.parent;
        }
        if (isShape) {
            hitPoint = hit.point;
            break;
        }
    }

    if (hitPoint) {
        const x = Math.round(hitPoint.x / SNAP_GRID) * SNAP_GRID;
        const z = Math.round(hitPoint.z / SNAP_GRID) * SNAP_GRID;
        let y = hitPoint.y;
        if (y < 0.05) y = 0;

        if (!currentPoint || 
            Math.abs(currentPoint.x - x) > 0.001 || 
            Math.abs(currentPoint.z - z) > 0.001 || 
            Math.abs(currentPoint.y - y) > 0.001) {
            setCurrentPoint({ x, y, z });
        }
    } else {
        if (currentPoint) setCurrentPoint(null);
    }
  });

  const handleClick = (e: ThreeEvent<MouseEvent>) => {
    if (tool === ToolType.SELECT || !currentPoint) return;
    e.stopPropagation();
    const p = { ...currentPoint };

    if (tool === ToolType.MEASURE) {
        if (!measureStart) {
            setMeasureStart(p);
            setMeasureEnd(null);
        } else {
            const dist = Math.sqrt(Math.pow(p.x - measureStart.x, 2) + Math.pow(p.z - measureStart.z, 2));
            if (dist > 0.01) {
                const newDimension: IShape = {
                    id: `dim-${Date.now()}`,
                    name: '尺寸標註',
                    type: 'dimension',
                    points: [measureStart, p], 
                    height: 0,
                    color: DIMENSION_COLOR,
                    position: [0, 0, 0],
                    rotation: 0,
                    scale: [1, 1, 1]
                };
                addShape(newDimension);
            }
            setMeasureStart(null);
            setMeasureEnd(null);
        }
        return;
    }

    if (tool === ToolType.DRAW_POLY) {
      if (polyPoints.length > 2) {
         const start = polyPoints[0];
         const dist = Math.sqrt(Math.pow(p.x - start.x, 2) + Math.pow(p.z - start.z, 2));
         if (dist < 0.5) {
           finishShape(polyPoints);
           return;
         }
      }
      setPolyPoints([...polyPoints, p]);
    } else {
      if (!startPoint) {
        setStartPoint(p);
      } else {
        finishPrimitive(startPoint, p);
      }
    }
  };

  const finishPrimitive = (start: IPoint, end: IPoint) => {
    let points: IPoint[] = [];
    let name = "平面";
    const cx = (start.x + end.x) / 2;
    const cz = (start.z + end.z) / 2;
    const y = start.y;

    const dx = end.x - start.x;
    const dz = end.z - start.z;
    const dist = Math.sqrt(dx*dx + dz*dz);

    if (dist < 0.1) return;

    let finalPos: [number, number, number] = [0,0,0];

    switch (tool) {
      case ToolType.DRAW_LINE:
        const thickness = 0.2; 
        const len = dist;
        points = [
          { x: 0, y: 0, z: -thickness/2 },
          { x: len, y: 0, z: -thickness/2 },
          { x: len, y: 0, z: thickness/2 },
          { x: 0, y: 0, z: thickness/2 },
          { x: 0, y: 0, z: -thickness/2 }
        ];
        finalPos = [start.x, y, start.z]; 
        name = "牆面";
        break;

      case ToolType.DRAW_RECT:
        const w = Math.abs(dx);
        const d = Math.abs(dz);
        finalPos = [cx, y, cz];
        points = [
          { x: -w/2, y: 0, z: -d/2 },
          { x: w/2, y: 0, z: -d/2 },
          { x: w/2, y: 0, z: d/2 },
          { x: -w/2, y: 0, z: d/2 },
          { x: -w/2, y: 0, z: -d/2 }
        ];
        name = "區域";
        break;

      case ToolType.DRAW_CIRCLE:
        finalPos = [start.x, y, start.z];
        points = createCirclePoints(dist);
        name = "圓形";
        break;

      case ToolType.DRAW_ARC:
        finalPos = [start.x, y, start.z];
        points = createArcPoints(dist);
        name = "開門";
        break;
    }

    let rotation = 0;
    if (tool === ToolType.DRAW_LINE || tool === ToolType.DRAW_ARC) {
       rotation = -Math.atan2(dz, dx); 
    }

    const newShape: IShape = {
      id: `shape-${Date.now()}`,
      name: `${name}`,
      type: 'flat',
      points,
      height: DEFAULT_HEIGHT,
      color: FLAT_COLOR,
      position: finalPos,
      rotation: rotation,
      scale: [1, 1, 1]
    };

    addShape(newShape);
    setStartPoint(null);
  };

  const finishShape = (pts: IPoint[]) => {
    if (pts.length < 3) return;
    const cx = pts.reduce((sum, p) => sum + p.x, 0) / pts.length;
    const cz = pts.reduce((sum, p) => sum + p.z, 0) / pts.length;
    const cy = pts[0].y;

    const centeredPoints = pts.map(p => ({ x: p.x - cx, y: 0, z: p.z - cz }));
    centeredPoints.push(centeredPoints[0]);

    const newShape: IShape = {
      id: `poly-${Date.now()}`,
      name: `多邊形`,
      type: 'flat',
      points: centeredPoints,
      height: DEFAULT_HEIGHT,
      color: FLAT_COLOR,
      position: [cx, cy, cz],
      rotation: 0,
      scale: [1, 1, 1]
    };
    addShape(newShape);
    setPolyPoints([]);
    setStartPoint(null);
  };

  const previewPoints = useMemo(() => {
     if (tool === ToolType.DRAW_POLY) {
        if (polyPoints.length === 0 && !currentPoint) return [];
        const pts = [...polyPoints];
        if (currentPoint) pts.push(currentPoint);
        return pts;
     }

     if (startPoint && currentPoint) {
         if (tool === ToolType.DRAW_LINE) {
             const thickness = 0.2;
             const dx = currentPoint.x - startPoint.x;
             const dz = currentPoint.z - startPoint.z;
             const len = Math.sqrt(dx*dx + dz*dz);
             if (len < 0.01) return [startPoint, currentPoint];
             const nx = -dz / len;
             const nz = dx / len;
             const ox = nx * (thickness / 2);
             const oz = nz * (thickness / 2);
             return [
               { x: startPoint.x + ox, y: 0, z: startPoint.z + oz },
               { x: currentPoint.x + ox, y: 0, z: currentPoint.z + oz },
               { x: currentPoint.x - ox, y: 0, z: currentPoint.z - oz },
               { x: startPoint.x - ox, y: 0, z: startPoint.z - oz },
               { x: startPoint.x + ox, y: 0, z: startPoint.z + oz },
             ];
         }
         if (tool === ToolType.DRAW_RECT) {
             return [
                 startPoint,
                 { x: currentPoint.x, y: 0, z: startPoint.z },
                 currentPoint,
                 { x: startPoint.x, y: 0, z: currentPoint.z },
                 startPoint
             ];
         }
         if (tool === ToolType.DRAW_CIRCLE) {
             const dist = Math.sqrt(Math.pow(currentPoint.x - startPoint.x, 2) + Math.pow(currentPoint.z - startPoint.z, 2));
             return createCirclePoints(dist, 64).map(p => ({
                 x: p.x + startPoint.x,
                 y: 0,
                 z: p.z + startPoint.z
             }));
         }
         if (tool === ToolType.DRAW_ARC) {
             const dist = Math.sqrt(Math.pow(currentPoint.x - startPoint.x, 2) + Math.pow(currentPoint.z - startPoint.z, 2));
             return createArcPoints(dist, 32).map(p => ({
                 x: p.x + startPoint.x,
                 y: 0,
                 z: p.z + startPoint.z
             }));
         }
     }
     return [];
  }, [tool, startPoint, currentPoint, polyPoints]);

  const drawY = useMemo(() => {
    if (startPoint) return startPoint.y;
    if (polyPoints.length > 0) return polyPoints[0].y;
    if (currentPoint) return currentPoint.y;
    return 0;
  }, [startPoint, polyPoints, currentPoint]);

  return (
    <>
      <mesh 
        name="ground_plane"
        rotation={[-Math.PI / 2, 0, 0]} 
        position={[0, -0.01, 0]} 
        onClick={handleClick}
      >
        <planeGeometry args={[100, 100]} />
        <meshBasicMaterial color="black" transparent opacity={0} />
      </mesh>

      {currentPoint && tool !== ToolType.SELECT && (
        <mesh name="cursor_helper" position={[currentPoint.x, currentPoint.y + 0.05, currentPoint.z]} rotation={[-Math.PI / 2, 0, 0]}>
          <ringGeometry args={[0.1, 0.15, 32]} />
          <meshBasicMaterial color="#ef4444" depthTest={false} />
        </mesh>
      )}

      {tool === ToolType.MEASURE && measureStart && (
        <>
            <Line 
                points={[
                    [measureStart.x, measureStart.y + 0.05, measureStart.z],
                    (() => {
                        const target = measureEnd || currentPoint || measureStart;
                        return [target.x, target.y + 0.05, target.z] as [number, number, number];
                    })()
                ]} 
                color="#facc15" 
                lineWidth={2} 
                dashed 
                dashScale={50}
                depthTest={false}
            />
            <mesh position={[measureStart.x, measureStart.y, measureStart.z]}>
                <sphereGeometry args={[0.08]} />
                <meshBasicMaterial color="#facc15" depthTest={false} />
            </mesh>
            {(measureEnd || currentPoint) && (
                <mesh position={(() => {
                    const p = measureEnd || currentPoint;
                    return p ? [p.x, p.y, p.z] : [0,0,0];
                })()}>
                    <sphereGeometry args={[0.08]} />
                    <meshBasicMaterial color="#facc15" depthTest={false} />
                </mesh>
            )}
            <CursorTooltip 
                position={(() => {
                    const target = measureEnd || currentPoint || measureStart;
                    return [
                        (measureStart.x + target.x) / 2,
                        measureStart.y + 0.5,
                        (measureStart.z + target.z) / 2
                    ] as [number, number, number];
                })()}
                text={(() => {
                    const target = measureEnd || currentPoint || measureStart;
                    const dist = Math.sqrt(
                        Math.pow(target.x - measureStart.x, 2) + 
                        Math.pow(target.z - measureStart.z, 2) +
                        Math.pow(target.y - measureStart.y, 2)
                    );
                    return `距離: ${formatValue(dist)}`;
                })()}
            />
        </>
      )}

      {currentPoint && (startPoint || polyPoints.length > 0) && tool !== ToolType.MEASURE && (
        <CursorTooltip 
           position={(() => {
               const prev = polyPoints.length > 0 ? polyPoints[polyPoints.length - 1] : startPoint;
               if (!prev) return [currentPoint.x, currentPoint.y + 0.5, currentPoint.z] as [number, number, number];

               return [
                 (prev.x + currentPoint.x)/2, 
                 prev.y + 0.5, 
                 (prev.z + currentPoint.z)/2
               ] as [number, number, number];
           })()}
           text={(() => {
             const prev = polyPoints.length > 0 ? polyPoints[polyPoints.length - 1] : startPoint;
             if (!prev) return '';

             const dx = Math.abs(currentPoint.x - prev.x);
             const dz = Math.abs(currentPoint.z - prev.z);
             const dist = Math.sqrt(Math.pow(currentPoint.x - prev.x, 2) + Math.pow(currentPoint.z - prev.z, 2));

             if (tool === ToolType.DRAW_RECT) return `${formatValue(dx)} x ${formatValue(dz)}`;
             if (tool === ToolType.DRAW_CIRCLE || tool === ToolType.DRAW_ARC) return `R: ${formatValue(dist)}`;
             return `L: ${formatValue(dist)}`;
           })()}
        />
      )}

      {previewPoints.length > 0 && (startPoint || polyPoints.length > 0) && (
         <PreviewFill points={previewPoints} y={drawY} />
      )}

      {previewPoints.length > 1 && (
        <Line 
           name="preview_helper"
           points={previewPoints.map(p => [p.x, drawY + 0.06, p.z] as [number, number, number])}
           color="#38bdf8"
           lineWidth={2}
           transparent
           opacity={0.8}
        />
      )}

      {tool === ToolType.DRAW_POLY && previewPoints.length > 0 && (
         <points>
           <bufferGeometry>
             <bufferAttribute
               attach="attributes-position"
               count={previewPoints.length}
               array={new Float32Array(previewPoints.flatMap(p => [p.x, drawY + 0.07, p.z]))}
               itemSize={3}
             />
           </bufferGeometry>
           <pointsMaterial color="#38bdf8" size={0.15} sizeAttenuation={true} depthTest={false} />
         </points>
      )}

      {tool === ToolType.DRAW_POLY && polyPoints.length > 0 && (
          <mesh position={[polyPoints[0].x, drawY + 0.05, polyPoints[0].z]}>
              <sphereGeometry args={[0.2]} />
              <meshBasicMaterial 
                color={
                  currentPoint && 
                  Math.sqrt(Math.pow(currentPoint.x - polyPoints[0].x, 2) + Math.pow(currentPoint.z - polyPoints[0].z, 2)) < 0.5 
                  ? "#10b981" 
                  : "#38bdf8" 
                } 
                depthTest={false} 
                transparent 
                opacity={0.8}
              />
          </mesh>
      )}
    </>
  );
};

const RenderedShape: React.FC<{ shape: IShape }> = ({ shape }) => {
  const { selectedId, setSelectedId, tool, updateShape, transformMode, formatValue, shapes } = useApp();
  const isSelected = selectedId === shape.id;
  const { scene, raycaster, camera, gl } = useThree();

  const groupRef = useRef<THREE.Group>(null);

  const threeShape = useMemo(() => {
    if (shape.type === 'dimension') return null;
    return createThreeShape(shape.points);
  }, [shape.points, shape.type]);

  const targetSnapPointsRef = useRef<SnapPoint[]>([]);
  const [activeSnap, setActiveSnap] = useState<{ start: [number, number, number], end: [number, number, number] } | null>(null);

  const [isTransforming, setIsTransforming] = useState(false);
  const [liveDimensions, setLiveDimensions] = useState<{ w: number, d: number, h: number } | null>(null);
  const baseDimensions = useMemo(() => getBaseDimensions(shape.points), [shape.points]);

  const [dragHandle, setDragHandle] = useState<{ axis: 'x' | 'z', direction: 1 | -1, startPoint: THREE.Vector3, anchorPointWorld: THREE.Vector3, startScale: THREE.Vector3 } | null>(null);

  const geometry = useMemo(() => {
    if (!threeShape || shape.type === 'dimension') return null;
    return new THREE.ExtrudeGeometry(threeShape, { depth: shape.height, bevelEnabled: false });
  }, [threeShape, shape.height, shape.type]);

  useEffect(() => {
    if (groupRef.current) {
        groupRef.current.position.set(shape.position[0], shape.position[1], shape.position[2]);
        groupRef.current.rotation.set(0, shape.rotation, 0); 
        groupRef.current.scale.set(shape.scale[0], shape.scale[1], shape.scale[2]);
    }
  }, [shape.position, shape.rotation, shape.scale]);

  const onHandleDragStart = (e: ThreeEvent<PointerEvent>, axis: 'x' | 'z', direction: 1 | -1) => {
      if (!groupRef.current) return;

      const point = e.point.clone(); 
      const target = groupRef.current;

      const { minX, maxX, minZ, maxZ, centerX, centerZ } = baseDimensions;

      let localAnchor: THREE.Vector3;
      if (axis === 'x') {
          const anchorX = direction === 1 ? minX : maxX;
          localAnchor = new THREE.Vector3(anchorX, 0, centerZ);
      } else {
          const anchorZ = direction === 1 ? minZ : maxZ;
          localAnchor = new THREE.Vector3(centerX, 0, anchorZ);
      }

      target.updateMatrixWorld();
      const anchorPointWorld = localAnchor.clone().applyMatrix4(target.matrixWorld);

      setDragHandle({
          axis,
          direction,
          startPoint: point,
          anchorPointWorld,
          startScale: target.scale.clone(),
      });
      setIsTransforming(true);

      const onPointerMove = (moveEvent: PointerEvent) => {
        if (!groupRef.current) return;

        const ndc = new THREE.Vector2(
             (moveEvent.clientX / window.innerWidth) * 2 - 1,
            -(moveEvent.clientY / window.innerHeight) * 2 + 1
        );
        raycaster.setFromCamera(ndc, camera);
        const plane = new THREE.Plane(new THREE.Vector3(0, 1, 0), -shape.position[1]);
        const targetPoint = new THREE.Vector3();
        raycaster.ray.intersectPlane(plane, targetPoint);

        if (targetPoint) {
           handleResizeDrag(targetPoint);
        }
      };

      const onPointerUp = () => {
          window.removeEventListener('pointermove', onPointerMove);
          window.removeEventListener('pointerup', onPointerUp);

          setDragHandle(null);
          setIsTransforming(false);
          setLiveDimensions(null);

          if (groupRef.current) {
              updateShape(shape.id, {
                  scale: [groupRef.current.scale.x, groupRef.current.scale.y, groupRef.current.scale.z],
                  position: [groupRef.current.position.x, groupRef.current.position.y, groupRef.current.position.z]
              });
          }
      };

      window.addEventListener('pointermove', onPointerMove);
      window.addEventListener('pointerup', onPointerUp);
  };

  const handleResizeDrag = (currentPoint: THREE.Vector3) => {
      if (!dragHandle || !groupRef.current) return;

      const { axis, direction, startPoint, startScale, anchorPointWorld } = dragHandle;
      const target = groupRef.current;

      const deltaWorld = currentPoint.clone().sub(startPoint);
      const rotationY = shape.rotation;
      const deltaLocal = deltaWorld.clone().applyAxisAngle(new THREE.Vector3(0, 1, 0), -rotationY);

      const change = axis === 'x' ? deltaLocal.x : deltaLocal.z;
      const baseSize = axis === 'x' ? baseDimensions.width : baseDimensions.depth;
      if (baseSize < 0.001) return;

      const scaleChange = (change * direction) / baseSize;

      let newScaleValue = (axis === 'x' ? startScale.x : startScale.z) + scaleChange;
      if (newScaleValue < 0.01) newScaleValue = 0.01;

      const newScale = startScale.clone();
      if (axis === 'x') newScale.x = newScaleValue;
      else newScale.z = newScaleValue;

      target.scale.copy(newScale);
      target.updateMatrixWorld();

      const { minX, maxX, minZ, maxZ, centerX, centerZ } = baseDimensions;
      let localAnchor: THREE.Vector3;
      if (axis === 'x') {
          const anchorX = direction === 1 ? minX : maxX;
          localAnchor = new THREE.Vector3(anchorX, 0, centerZ);
      } else {
          const anchorZ = direction === 1 ? minZ : maxZ;
          localAnchor = new THREE.Vector3(centerX, 0, anchorZ);
      }

      const currentAnchorWorld = localAnchor.clone().applyMatrix4(target.matrixWorld);

      const shift = anchorPointWorld.clone().sub(currentAnchorWorld);
      target.position.add(shift);

      setLiveDimensions({
          w: baseDimensions.width * newScale.x,
          d: baseDimensions.depth * newScale.z,
          h: shape.height * startScale.y
      });
  };

  const handleDragStart = () => {
    setIsTransforming(true);
    const others = shapes.filter(s => s.id !== shape.id);
    let allPoints: SnapPoint[] = [];
    others.forEach(s => {
        allPoints = [...allPoints, ...getSnapCandidates(s)];
    });
    targetSnapPointsRef.current = allPoints;
    setActiveSnap(null);
  };

  const handleDragEnd = () => {
    setIsTransforming(false);
    setLiveDimensions(null);
    if (groupRef.current) {
        updateShape(shape.id, {
            position: [groupRef.current.position.x, groupRef.current.position.y, groupRef.current.position.z],
            rotation: groupRef.current.rotation.y,
            scale: [groupRef.current.scale.x, groupRef.current.scale.y, groupRef.current.scale.z]
        });
    }
    targetSnapPointsRef.current = [];
    setActiveSnap(null);
  };

  const handleObjectChange = (e: any) => {
      if (!groupRef.current) return;
      const target = groupRef.current;

      if (transformMode === 'scale') {
          const s = target.scale;
          setLiveDimensions({
              w: baseDimensions.width * s.x,
              d: baseDimensions.depth * s.z,
              h: shape.height * s.y
          });
          return;
      }

      if (transformMode !== 'translate') return;

      target.updateMatrixWorld();
      const mat = target.matrixWorld;
      let currentPoints: { local: THREE.Vector3, world: THREE.Vector3 }[] = [];

      if (shape.type !== 'dimension') {
          const { centerX, centerZ } = baseDimensions;
          const centerBot = new THREE.Vector3(centerX, 0, centerZ);
          currentPoints.push({ local: centerBot.clone(), world: centerBot.applyMatrix4(mat).clone() });

          shape.points.forEach(p => {
              const vBot = new THREE.Vector3(p.x, 0, p.z);
              currentPoints.push({ local: vBot.clone(), world: vBot.applyMatrix4(mat).clone() });
          });
      }

      let bestDist = 0.3; 
      let snapMatch: { sourceLocal: THREE.Vector3, targetWorld: THREE.Vector3 } | null = null;

      for (const source of currentPoints) {
          for (const targetPt of targetSnapPointsRef.current) {
              const dist = source.world.distanceTo(targetPt.pos);
              if (dist < bestDist) {
                  bestDist = dist;
                  snapMatch = { sourceLocal: source.local, targetWorld: targetPt.pos };
              }
          }
      }

      if (snapMatch) {
          const offset = snapMatch.sourceLocal.clone()
             .applyEuler(target.rotation)
             .multiply(target.scale);

          const newPos = snapMatch.targetWorld.clone().sub(offset);
          target.position.copy(newPos);

          const startVec = newPos.clone().add(offset);
          const endVec = snapMatch.targetWorld;

          setActiveSnap({ 
              start: [startVec.x, startVec.y, startVec.z], 
              end: [endVec.x, endVec.y, endVec.z] 
          });
      } else {
          setActiveSnap(null);
          if (Math.abs(target.position.y) < 0.1) {
              target.position.y = 0;
          }
      }
  };

  const handleHeightChange = (e: any) => {
    if (e.target.object) {
      const newHeight = e.target.object.position.y;
      if (newHeight > 0.01) {
        const isNowSolid = newHeight > 0.1;
        updateShape(shape.id, { 
          height: newHeight,
          type: isNowSolid ? 'solid' : 'flat',
          color: isNowSolid && shape.color === FLAT_COLOR ? DEFAULT_COLOR : shape.color
        });
      }
    }
  };

  if (shape.type === 'dimension') {
      const p1 = shape.points[0];
      const p2 = shape.points[1];
      const dist = Math.sqrt(Math.pow(p2.x - p1.x, 2) + Math.pow(p2.z - p1.z, 2) + Math.pow(p2.y - p1.y, 2));
      const midX = (p1.x + p2.x) / 2;
      const midY = (p1.y + p2.y) / 2 + 0.1;
      const midZ = (p1.z + p2.z) / 2;

      return (
        <group 
            ref={groupRef}
            userData={{ isShape: true, id: shape.id }}
            onClick={(e) => {
                if (tool === ToolType.SELECT) {
                    e.stopPropagation();
                    setSelectedId(shape.id);
                }
            }}
        >
            <Line 
                points={[[p1.x, p1.y + 0.05, p1.z], [p2.x, p2.y + 0.05, p2.z]]} 
                color={isSelected ? HIGHLIGHT_COLOR : shape.color} 
                lineWidth={3} 
                dashed 
                dashScale={10}
            />
            <mesh position={[p1.x, p1.y + 0.05, p1.z]}>
                <sphereGeometry args={[0.06]} />
                <meshBasicMaterial color={isSelected ? HIGHLIGHT_COLOR : shape.color} />
            </mesh>
            <mesh position={[p2.x, p2.y + 0.05, p2.z]}>
                <sphereGeometry args={[0.06]} />
                <meshBasicMaterial color={isSelected ? HIGHLIGHT_COLOR : shape.color} />
            </mesh>
            <Html position={[midX, midY, midZ]} center style={{ pointerEvents: 'none' }}>
                <div 
                    className={`text-xs px-2 py-1 rounded whitespace-nowrap backdrop-blur-sm border ${
                        isSelected 
                        ? 'bg-blue-600/90 text-white border-blue-400' 
                        : 'bg-black/70 text-yellow-400 border-yellow-500/50'
                    }`}
                >
                    {formatValue(dist)}
                </div>
            </Html>
        </group>
      );
  }

  const { minX, maxX, minZ, maxZ, centerX, centerZ } = baseDimensions;
  const hPos = shape.height / 2;
  const offset = 0.4; 

  return (
    <>
      {isSelected && tool === ToolType.SELECT && (
        <TransformControls
            object={groupRef}
            mode={transformMode === 'scale' ? 'scale' : 'translate'}
            enabled={transformMode === 'translate'}
            showY={true} showX={true} showZ={true}
            onMouseDown={handleDragStart}
            onMouseUp={handleDragEnd}
            onObjectChange={handleObjectChange}
        />
      )}

      {isSelected && activeSnap && <SnapIndicator start={activeSnap.start} end={activeSnap.end} />}

      {isSelected && isTransforming && liveDimensions && (
         <Html position={[0, shape.height + 0.5, 0]} center style={{ pointerEvents: 'none' }}>
            <div className="flex flex-col gap-1 bg-black/80 text-white text-xs p-2 rounded backdrop-blur-sm border border-white/20 shadow-xl z-50">
               <div className="flex justify-between gap-3"><span>寬(W):</span> <span className="font-mono text-blue-300">{formatValue(liveDimensions.w)}</span></div>
               <div className="flex justify-between gap-3"><span>深(D):</span> <span className="font-mono text-green-300">{formatValue(liveDimensions.d)}</span></div>
               <div className="flex justify-between gap-3"><span>高(H):</span> <span className="font-mono text-yellow-300">{formatValue(liveDimensions.h)}</span></div>
            </div>
         </Html>
      )}

      {isSelected && tool === ToolType.SELECT && (
        <TransformControls
            mode="translate"
            position={[shape.position[0], shape.height, shape.position[2]]} 
            showX={false} showZ={false} showY={true}
            translationSnap={0.05}
            onObjectChange={handleHeightChange}
        >
            <mesh>
              <boxGeometry args={[0.3, 0.3, 0.3]} />
              <meshBasicMaterial color="#4ade80" depthTest={false} transparent opacity={0.8} />
            </mesh>
            <Html position={[0.4, 0, 0]} center style={{ pointerEvents: 'none' }}>
                <div className="bg-green-500 text-white text-xs px-1 rounded font-mono shadow-md whitespace-nowrap">
                    H: {formatValue(shape.height)}
                </div>
            </Html>
        </TransformControls>
      )}

      <group 
        ref={groupRef}
        userData={{ isShape: true, id: shape.id }}
        onClick={(e) => {
          if (tool === ToolType.SELECT) {
            e.stopPropagation();
            setSelectedId(shape.id);
          }
        }}
      >
        <mesh rotation={[-Math.PI / 2, 0, 0]}>
            <primitive object={geometry} attach="geometry" />
            <meshStandardMaterial 
              color={isSelected ? HIGHLIGHT_COLOR : shape.color} 
              transparent={isSelected || shape.type === 'flat'} 
              opacity={shape.type === 'flat' ? 0.6 : (isSelected ? 0.9 : 1)}
              side={THREE.DoubleSide}
            />
            {isSelected && (
              <lineSegments>
                <edgesGeometry args={[geometry]} />
                <lineBasicMaterial color="white" />
              </lineSegments>
            )}
        </mesh>

        {/* --- Custom Smart Resize Gizmos --- */}
        {isSelected && tool === ToolType.SELECT && (
            <group>
                {/* 
                  Note on offsets:
                  The handles are children of the scaled group. 
                  Therefore, a fixed world offset (e.g. 0.4m) must be divided by the scale to result in the correct local position.
                  pos = minX + (offset / scaleX)
                */}
                <ResizeHandle 
                    position={[maxX + offset / shape.scale[0], hPos, centerZ]} 
                    parentScale={shape.scale}
                    axis="x" 
                    direction={1} 
                    onDragStart={onHandleDragStart} 
                    color="#ef4444"
                />
                 <ResizeHandle 
                    position={[minX - offset / shape.scale[0], hPos, centerZ]} 
                    parentScale={shape.scale}
                    axis="x" 
                    direction={-1} 
                    onDragStart={onHandleDragStart} 
                    color="#ef4444" 
                />
                 <ResizeHandle 
                    position={[centerX, hPos, maxZ + offset / shape.scale[2]]} 
                    parentScale={shape.scale}
                    axis="z" 
                    direction={1} 
                    onDragStart={onHandleDragStart} 
                    color="#3b82f6"
                />
                 <ResizeHandle 
                    position={[centerX, hPos, minZ - offset / shape.scale[2]]} 
                    parentScale={shape.scale}
                    axis="z" 
                    direction={-1} 
                    onDragStart={onHandleDragStart} 
                    color="#3b82f6"
                />
            </group>
        )}
      </group>
    </>
  );
};

import React, { useRef, useState, useMemo, useEffect } from 'react';
import { Canvas, useThree, ThreeEvent, useFrame } from '@react-three/fiber';
import { OrbitControls, Grid, Environment, TransformControls, Html, Line, GizmoHelper, GizmoViewport } from '@react-three/drei';
import * as THREE from 'three';
import { useApp } from '../context/AppContext';
import { ToolType, IPoint, IShape, ShapeType } from '../types';
import { SNAP_GRID, DEFAULT_COLOR, FLAT_COLOR, HIGHLIGHT_COLOR, DIMENSION_COLOR, DEFAULT_HEIGHT } from '../constants';

// --- Types for Snapping ---
interface SnapPoint {
    pos: THREE.Vector3;
    type: 'vertex' | 'center' | 'midpoint';
}

// --- Helpers ---

// Convert 2D points to Three Shape
// Note: We negate Z when mapping to Shape Y because the mesh is rotated -90 degrees around X.
// This rotation maps Shape Y to World -Z. By negating here (-Z), we get (-(-Z)) = World Z.
const createThreeShape = (points: IPoint[]) => {
  const shape = new THREE.Shape();
  if (!points || points.length === 0) return shape;

  if (points[0]) {
    shape.moveTo(points[0].x, -points[0].z); 
    for (let i = 1; i < points.length; i++) {
        if (points[i]) {
            shape.lineTo(points[i].x, -points[i].z);
        }
    }
  }
  shape.closePath();
  return shape;
};

// Generate points for a circle
const createCirclePoints = (radius: number, segments = 32): IPoint[] => {
  const points: IPoint[] = [];
  for (let i = 0; i < segments; i++) {
    const theta = (i / segments) * Math.PI * 2;
    points.push({ x: Math.cos(theta) * radius, y: 0, z: Math.sin(theta) * radius });
  }
  points.push(points[0]);
  return points;
};

// Generate points for a quarter arc
const createArcPoints = (radius: number, segments = 16): IPoint[] => {
  const points: IPoint[] = [];
  points.push({ x: 0, y: 0, z: 0 });
  for (let i = 0; i <= segments; i++) {
    const theta = (i / segments) * (Math.PI / 2); // 90 degrees
    points.push({ x: Math.cos(theta) * radius, y: 0, z: Math.sin(theta) * radius });
  }
  points.push({ x: 0, y: 0, z: 0 });
  return points;
};

// Calculate all snap candidates for a shape (Vertices, Midpoints, Centers - Top & Bottom)
const getSnapCandidates = (shape: IShape): SnapPoint[] => {
    // Dimensions don't offer snap points to avoid clutter
    if (shape.type === 'dimension') return [];

    const candidates: SnapPoint[] = [];
    const mat = new THREE.Matrix4();
    const quaternion = new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(0, 1, 0), shape.rotation);
    const scale = new THREE.Vector3(shape.scale[0], shape.scale[1], shape.scale[2]);
    const position = new THREE.Vector3(shape.position[0], shape.position[1], shape.position[2]);

    mat.compose(position, quaternion, scale);

    // 1. Center (Bottom & Top)
    // Calculate centroid of the base polygon
    let cx = 0, cz = 0;
    if (shape.points && shape.points.length > 0) {
        shape.points.forEach(p => { cx += p.x; cz += p.z; });
        cx /= shape.points.length;
        cz /= shape.points.length;
    }

    const localCenterBottom = new THREE.Vector3(cx, 0, cz);
    const localCenterTop = new THREE.Vector3(cx, shape.height, cz);

    candidates.push({ pos: localCenterBottom.applyMatrix4(mat).clone(), type: 'center' });
    candidates.push({ pos: localCenterTop.applyMatrix4(mat).clone(), type: 'center' });

    // 2. Vertices & Midpoints
    if (shape.points) {
        for (let i = 0; i < shape.points.length; i++) {
            const p = shape.points[i];
            const nextP = shape.points[(i + 1) % shape.points.length];

            // Vertices (Bottom & Top)
            const vBottom = new THREE.Vector3(p.x, 0, p.z);
            const vTop = new THREE.Vector3(p.x, shape.height, p.z);

            candidates.push({ pos: vBottom.clone().applyMatrix4(mat), type: 'vertex' });
            candidates.push({ pos: vTop.clone().applyMatrix4(mat), type: 'vertex' });

            // Midpoints (Bottom & Top)
            const midX = (p.x + nextP.x) / 2;
            const midZ = (p.z + nextP.z) / 2;

            const mBottom = new THREE.Vector3(midX, 0, midZ);
            const mTop = new THREE.Vector3(midX, shape.height, midZ);

            candidates.push({ pos: mBottom.clone().applyMatrix4(mat), type: 'midpoint' });
            candidates.push({ pos: mTop.clone().applyMatrix4(mat), type: 'midpoint' });
        }
    }

    return candidates;
};

// Calculate base dimensions (width/depth) from points
const getBaseDimensions = (points: IPoint[]) => {
    if (!points || points.length === 0) return { width: 0, depth: 0, minX: 0, maxX: 0, minZ: 0, maxZ: 0, centerX: 0, centerZ: 0 };
    let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity;
    points.forEach(p => {
        minX = Math.min(minX, p.x);
        maxX = Math.max(maxX, p.x);
        minZ = Math.min(minZ, p.z);
        maxZ = Math.max(maxZ, p.z);
    });
    return { 
        width: maxX - minX || 0.1, 
        depth: maxZ - minZ || 0.1,
        minX, maxX, minZ, maxZ,
        centerX: (minX + maxX) / 2,
        centerZ: (minZ + maxZ) / 2
    };
};

// --- Components ---

const CursorTooltip: React.FC<{ text: string; position: THREE.Vector3 | [number, number, number] }> = ({ text, position }) => {
  const pos = Array.isArray(position) ? position : [position.x, 0.5, position.z];
  return (
    <Html position={[pos[0], 0.5, pos[2]]} center style={{ pointerEvents: 'none' }}>
      <div className="bg-black/80 text-white text-xs px-2 py-1 rounded whitespace-nowrap backdrop-blur-sm border border-white/20">
        {text}
      </div>
    </Html>
  );
};

const PreviewFill: React.FC<{ points: IPoint[], y: number }> = ({ points, y }) => {
  const shape = useMemo(() => {
    if (!points || points.length < 3) return null;
    const s = new THREE.Shape();
    if (points[0]) {
      s.moveTo(points[0].x, -points[0].z); // Invert Z here too for consistency if we used rotation elsewhere
      // However, PreviewFill uses 'shapeGeometry' lying flat with -Math.PI/2 rotation.
      // So yes, we need -z here as well to match the standard behavior.
      for (let i = 1; i < points.length; i++) {
        if (points[i]) {
            s.lineTo(points[i].x, -points[i].z);
        }
      }
    }
    s.closePath();
    return s;
  }, [points]);

  if (!shape) return null;

  return (
    <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, y + 0.02, 0]}>
      <shapeGeometry args={[shape]} />
      <meshBasicMaterial color="#38bdf8" transparent opacity={0.3} side={THREE.DoubleSide} depthTest={false} />
    </mesh>
  );
};

const SnapIndicator: React.FC<{ start: [number, number, number]; end: [number, number, number] }> = ({ start, end }) => {
    return (
        <group>
            <Line 
                points={[start, end]} 
                color="#d946ef" 
                lineWidth={2} 
                depthTest={false} 
            />
            {/* Start Point */}
            <mesh position={start}>
                <sphereGeometry args={[0.08]} />
                <meshBasicMaterial color="#d946ef" depthTest={false} />
            </mesh>
            {/* End Point */}
            <mesh position={end}>
                <sphereGeometry args={[0.08]} />
                <meshBasicMaterial color="#d946ef" depthTest={false} />
            </mesh>
        </group>
    );
};

// New Component: Resize Handle Gizmo
interface ResizeHandleProps {
  position: [number, number, number];
  parentScale: [number, number, number];
  axis: 'x' | 'z';
  direction: 1 | -1;
  onDragStart: (e: ThreeEvent<PointerEvent>, axis: 'x' | 'z', direction: 1 | -1) => void;
  color: string;
}

const ResizeHandle: React.FC<ResizeHandleProps> = ({ position, parentScale, axis, direction, onDragStart, color }) => {
  const [hovered, setHovered] = useState(false);

  // Inverse scale to keep handle size constant (e.g. 0.4 units in world space)
  const scaleX = 1 / Math.max(0.001, parentScale[0]);
  const scaleY = 1 / Math.max(0.001, parentScale[1]);
  const scaleZ = 1 / Math.max(0.001, parentScale[2]);

  return (
    <mesh
      position={position}
      scale={[scaleX, scaleY, scaleZ]}
      onPointerOver={() => setHovered(true)}
      onPointerOut={() => setHovered(false)}
      onPointerDown={(e) => {
        e.stopPropagation();
        onDragStart(e, axis, direction);
      }}
      renderOrder={999} // Always render on top
    >
      <boxGeometry args={[0.4, 0.4, 0.4]} />
      <meshBasicMaterial 
        color={hovered ? 'white' : color} 
        depthTest={false}
        transparent
        opacity={1}
      />
      {/* Outline for visibility */}
      <lineSegments>
        <edgesGeometry args={[new THREE.BoxGeometry(0.4, 0.4, 0.4)]} />
        <lineBasicMaterial color="black" depthTest={false} opacity={0.5} transparent />
      </lineSegments>
    </mesh>
  );
};

const DrawingManager: React.FC = () => {
  const { tool, addShape, formatValue } = useApp();
  const [startPoint, setStartPoint] = useState<IPoint | null>(null);
  const [currentPoint, setCurrentPoint] = useState<IPoint | null>(null);
  const [polyPoints, setPolyPoints] = useState<IPoint[]>([]);

  // Measure Tool State
  const [measureStart, setMeasureStart] = useState<IPoint | null>(null);
  const [measureEnd, setMeasureEnd] = useState<IPoint | null>(null);

  const { raycaster, scene, camera } = useThree();

  useEffect(() => {
    setStartPoint(null);
    setCurrentPoint(null);
    setPolyPoints([]);
    setMeasureStart(null);
    setMeasureEnd(null);
  }, [tool]);

  useFrame(({ pointer }) => {
    if (tool === ToolType.SELECT) {
        if (currentPoint) setCurrentPoint(null);
        return;
    }

    raycaster.setFromCamera(pointer, camera);

    const interactables = scene.children.filter(obj => 
        obj.name === 'ground_plane' || 
        obj.userData?.isShape
    );

    const intersects = raycaster.intersectObjects(interactables, true);

    let hitPoint: THREE.Vector3 | null = null;

    for (const hit of intersects) {
        if (hit.object.name === 'cursor_helper' || hit.object.name === 'preview_helper') continue;
        if (hit.object.name === 'ground_plane') {
            hitPoint = hit.point;
            break;
        }
        let obj: THREE.Object3D | null = hit.object;
        let isShape = false;
        while(obj) {
            if (obj.userData?.isShape) {
                isShape = true;
                break;
            }
            obj = obj.parent;
        }
        if (isShape) {
            hitPoint = hit.point;
            break;
        }
    }

    if (hitPoint) {
        const x = Math.round(hitPoint.x / SNAP_GRID) * SNAP_GRID;
        const z = Math.round(hitPoint.z / SNAP_GRID) * SNAP_GRID;
        let y = hitPoint.y;
        if (y < 0.05) y = 0;

        if (!currentPoint || 
            Math.abs(currentPoint.x - x) > 0.001 || 
            Math.abs(currentPoint.z - z) > 0.001 || 
            Math.abs(currentPoint.y - y) > 0.001) {
            setCurrentPoint({ x, y, z });
        }
    } else {
        if (currentPoint) setCurrentPoint(null);
    }
  });

  const handleClick = (e: ThreeEvent<MouseEvent>) => {
    if (tool === ToolType.SELECT || !currentPoint) return;
    e.stopPropagation();
    const p = { ...currentPoint };

    if (tool === ToolType.MEASURE) {
        if (!measureStart) {
            setMeasureStart(p);
            setMeasureEnd(null);
        } else {
            const dist = Math.sqrt(Math.pow(p.x - measureStart.x, 2) + Math.pow(p.z - measureStart.z, 2));
            if (dist > 0.01) {
                const newDimension: IShape = {
                    id: `dim-${Date.now()}`,
                    name: '尺寸標註',
                    type: 'dimension',
                    points: [measureStart, p], 
                    height: 0,
                    color: DIMENSION_COLOR,
                    position: [0, 0, 0],
                    rotation: 0,
                    scale: [1, 1, 1]
                };
                addShape(newDimension);
            }
            setMeasureStart(null);
            setMeasureEnd(null);
        }
        return;
    }

    if (tool === ToolType.DRAW_POLY) {
      if (polyPoints.length > 2) {
         const start = polyPoints[0];
         const dist = Math.sqrt(Math.pow(p.x - start.x, 2) + Math.pow(p.z - start.z, 2));
         if (dist < 0.5) {
           finishShape(polyPoints);
           return;
         }
      }
      setPolyPoints([...polyPoints, p]);
    } else {
      if (!startPoint) {
        setStartPoint(p);
      } else {
        finishPrimitive(startPoint, p);
      }
    }
  };

  const finishPrimitive = (start: IPoint, end: IPoint) => {
    let points: IPoint[] = [];
    let name = "平面";
    const cx = (start.x + end.x) / 2;
    const cz = (start.z + end.z) / 2;
    const y = start.y;

    const dx = end.x - start.x;
    const dz = end.z - start.z;
    const dist = Math.sqrt(dx*dx + dz*dz);

    if (dist < 0.1) return;

    let finalPos: [number, number, number] = [0,0,0];

    switch (tool) {
      case ToolType.DRAW_LINE:
        const thickness = 0.2; 
        const len = dist;
        points = [
          { x: 0, y: 0, z: -thickness/2 },
          { x: len, y: 0, z: -thickness/2 },
          { x: len, y: 0, z: thickness/2 },
          { x: 0, y: 0, z: thickness/2 },
          { x: 0, y: 0, z: -thickness/2 }
        ];
        finalPos = [start.x, y, start.z]; 
        name = "牆面";
        break;

      case ToolType.DRAW_RECT:
        const w = Math.abs(dx);
        const d = Math.abs(dz);
        finalPos = [cx, y, cz];
        points = [
          { x: -w/2, y: 0, z: -d/2 },
          { x: w/2, y: 0, z: -d/2 },
          { x: w/2, y: 0, z: d/2 },
          { x: -w/2, y: 0, z: d/2 },
          { x: -w/2, y: 0, z: -d/2 }
        ];
        name = "區域";
        break;

      case ToolType.DRAW_CIRCLE:
        finalPos = [start.x, y, start.z];
        points = createCirclePoints(dist);
        name = "圓形";
        break;

      case ToolType.DRAW_ARC:
        finalPos = [start.x, y, start.z];
        points = createArcPoints(dist);
        name = "開門";
        break;
    }

    let rotation = 0;
    if (tool === ToolType.DRAW_LINE || tool === ToolType.DRAW_ARC) {
       rotation = -Math.atan2(dz, dx); 
    }

    const newShape: IShape = {
      id: `shape-${Date.now()}`,
      name: `${name}`,
      type: 'flat',
      points,
      height: DEFAULT_HEIGHT,
      color: FLAT_COLOR,
      position: finalPos,
      rotation: rotation,
      scale: [1, 1, 1]
    };

    addShape(newShape);
    setStartPoint(null);
  };

  const finishShape = (pts: IPoint[]) => {
    if (pts.length < 3) return;
    const cx = pts.reduce((sum, p) => sum + p.x, 0) / pts.length;
    const cz = pts.reduce((sum, p) => sum + p.z, 0) / pts.length;
    const cy = pts[0].y;

    const centeredPoints = pts.map(p => ({ x: p.x - cx, y: 0, z: p.z - cz }));
    centeredPoints.push(centeredPoints[0]);

    const newShape: IShape = {
      id: `poly-${Date.now()}`,
      name: `多邊形`,
      type: 'flat',
      points: centeredPoints,
      height: DEFAULT_HEIGHT,
      color: FLAT_COLOR,
      position: [cx, cy, cz],
      rotation: 0,
      scale: [1, 1, 1]
    };
    addShape(newShape);
    setPolyPoints([]);
    setStartPoint(null);
  };

  const previewPoints = useMemo(() => {
     if (tool === ToolType.DRAW_POLY) {
        if (polyPoints.length === 0 && !currentPoint) return [];
        const pts = [...polyPoints];
        if (currentPoint) pts.push(currentPoint);
        return pts;
     }

     if (startPoint && currentPoint) {
         if (tool === ToolType.DRAW_LINE) {
             const thickness = 0.2;
             const dx = currentPoint.x - startPoint.x;
             const dz = currentPoint.z - startPoint.z;
             const len = Math.sqrt(dx*dx + dz*dz);
             if (len < 0.01) return [startPoint, currentPoint];
             const nx = -dz / len;
             const nz = dx / len;
             const ox = nx * (thickness / 2);
             const oz = nz * (thickness / 2);
             return [
               { x: startPoint.x + ox, y: 0, z: startPoint.z + oz },
               { x: currentPoint.x + ox, y: 0, z: currentPoint.z + oz },
               { x: currentPoint.x - ox, y: 0, z: currentPoint.z - oz },
               { x: startPoint.x - ox, y: 0, z: startPoint.z - oz },
               { x: startPoint.x + ox, y: 0, z: startPoint.z + oz },
             ];
         }
         if (tool === ToolType.DRAW_RECT) {
             return [
                 startPoint,
                 { x: currentPoint.x, y: 0, z: startPoint.z },
                 currentPoint,
                 { x: startPoint.x, y: 0, z: currentPoint.z },
                 startPoint
             ];
         }
         if (tool === ToolType.DRAW_CIRCLE) {
             const dist = Math.sqrt(Math.pow(currentPoint.x - startPoint.x, 2) + Math.pow(currentPoint.z - startPoint.z, 2));
             return createCirclePoints(dist, 64).map(p => ({
                 x: p.x + startPoint.x,
                 y: 0,
                 z: p.z + startPoint.z
             }));
         }
         if (tool === ToolType.DRAW_ARC) {
             const dist = Math.sqrt(Math.pow(currentPoint.x - startPoint.x, 2) + Math.pow(currentPoint.z - startPoint.z, 2));
             return createArcPoints(dist, 32).map(p => ({
                 x: p.x + startPoint.x,
                 y: 0,
                 z: p.z + startPoint.z
             }));
         }
     }
     return [];
  }, [tool, startPoint, currentPoint, polyPoints]);

  const drawY = useMemo(() => {
    if (startPoint) return startPoint.y;
    if (polyPoints.length > 0) return polyPoints[0].y;
    if (currentPoint) return currentPoint.y;
    return 0;
  }, [startPoint, polyPoints, currentPoint]);

  return (
    <>
      <mesh 
        name="ground_plane"
        rotation={[-Math.PI / 2, 0, 0]} 
        position={[0, -0.01, 0]} 
        onClick={handleClick}
      >
        <planeGeometry args={[100, 100]} />
        <meshBasicMaterial color="black" transparent opacity={0} />
      </mesh>

      {currentPoint && tool !== ToolType.SELECT && (
        <mesh name="cursor_helper" position={[currentPoint.x, currentPoint.y + 0.05, currentPoint.z]} rotation={[-Math.PI / 2, 0, 0]}>
          <ringGeometry args={[0.1, 0.15, 32]} />
          <meshBasicMaterial color="#ef4444" depthTest={false} />
        </mesh>
      )}

      {tool === ToolType.MEASURE && measureStart && (
        <>
            <Line 
                points={[
                    [measureStart.x, measureStart.y + 0.05, measureStart.z],
                    (() => {
                        const target = measureEnd || currentPoint || measureStart;
                        return [target.x, target.y + 0.05, target.z] as [number, number, number];
                    })()
                ]} 
                color="#facc15" 
                lineWidth={2} 
                dashed 
                dashScale={50}
                depthTest={false}
            />
            <mesh position={[measureStart.x, measureStart.y, measureStart.z]}>
                <sphereGeometry args={[0.08]} />
                <meshBasicMaterial color="#facc15" depthTest={false} />
            </mesh>
            {(measureEnd || currentPoint) && (
                <mesh position={(() => {
                    const p = measureEnd || currentPoint;
                    return p ? [p.x, p.y, p.z] : [0,0,0];
                })()}>
                    <sphereGeometry args={[0.08]} />
                    <meshBasicMaterial color="#facc15" depthTest={false} />
                </mesh>
            )}
            <CursorTooltip 
                position={(() => {
                    const target = measureEnd || currentPoint || measureStart;
                    return [
                        (measureStart.x + target.x) / 2,
                        measureStart.y + 0.5,
                        (measureStart.z + target.z) / 2
                    ] as [number, number, number];
                })()}
                text={(() => {
                    const target = measureEnd || currentPoint || measureStart;
                    const dist = Math.sqrt(
                        Math.pow(target.x - measureStart.x, 2) + 
                        Math.pow(target.z - measureStart.z, 2) +
                        Math.pow(target.y - measureStart.y, 2)
                    );
                    return `距離: ${formatValue(dist)}`;
                })()}
            />
        </>
      )}

      {currentPoint && (startPoint || polyPoints.length > 0) && tool !== ToolType.MEASURE && (
        <CursorTooltip 
           position={(() => {
               const prev = polyPoints.length > 0 ? polyPoints[polyPoints.length - 1] : startPoint;
               if (!prev) return [currentPoint.x, currentPoint.y + 0.5, currentPoint.z] as [number, number, number];

               return [
                 (prev.x + currentPoint.x)/2, 
                 prev.y + 0.5, 
                 (prev.z + currentPoint.z)/2
               ] as [number, number, number];
           })()}
           text={(() => {
             const prev = polyPoints.length > 0 ? polyPoints[polyPoints.length - 1] : startPoint;
             if (!prev) return '';

             const dx = Math.abs(currentPoint.x - prev.x);
             const dz = Math.abs(currentPoint.z - prev.z);
             const dist = Math.sqrt(Math.pow(currentPoint.x - prev.x, 2) + Math.pow(currentPoint.z - prev.z, 2));

             if (tool === ToolType.DRAW_RECT) return `${formatValue(dx)} x ${formatValue(dz)}`;
             if (tool === ToolType.DRAW_CIRCLE || tool === ToolType.DRAW_ARC) return `R: ${formatValue(dist)}`;
             return `L: ${formatValue(dist)}`;
           })()}
        />
      )}

      {previewPoints.length > 0 && (startPoint || polyPoints.length > 0) && (
         <PreviewFill points={previewPoints} y={drawY} />
      )}

      {previewPoints.length > 1 && (
        <Line 
           name="preview_helper"
           points={previewPoints.map(p => [p.x, drawY + 0.06, p.z] as [number, number, number])}
           color="#38bdf8"
           lineWidth={2}
           transparent
           opacity={0.8}
        />
      )}

      {tool === ToolType.DRAW_POLY && previewPoints.length > 0 && (
         <points>
           <bufferGeometry>
             <bufferAttribute
               attach="attributes-position"
               count={previewPoints.length}
               array={new Float32Array(previewPoints.flatMap(p => [p.x, drawY + 0.07, p.z]))}
               itemSize={3}
             />
           </bufferGeometry>
           <pointsMaterial color="#38bdf8" size={0.15} sizeAttenuation={true} depthTest={false} />
         </points>
      )}

      {tool === ToolType.DRAW_POLY && polyPoints.length > 0 && (
          <mesh position={[polyPoints[0].x, drawY + 0.05, polyPoints[0].z]}>
              <sphereGeometry args={[0.2]} />
              <meshBasicMaterial 
                color={
                  currentPoint && 
                  Math.sqrt(Math.pow(currentPoint.x - polyPoints[0].x, 2) + Math.pow(currentPoint.z - polyPoints[0].z, 2)) < 0.5 
                  ? "#10b981" 
                  : "#38bdf8" 
                } 
                depthTest={false} 
                transparent 
                opacity={0.8}
              />
          </mesh>
      )}
    </>
  );
};

const RenderedShape: React.FC<{ shape: IShape }> = ({ shape }) => {
  const { selectedId, setSelectedId, tool, updateShape, transformMode, formatValue, shapes } = useApp();
  const isSelected = selectedId === shape.id;
  const { scene, raycaster, camera, gl } = useThree();

  const groupRef = useRef<THREE.Group>(null);

  const threeShape = useMemo(() => {
    if (shape.type === 'dimension') return null;
    return createThreeShape(shape.points);
  }, [shape.points, shape.type]);

  const targetSnapPointsRef = useRef<SnapPoint[]>([]);
  const [activeSnap, setActiveSnap] = useState<{ start: [number, number, number], end: [number, number, number] } | null>(null);

  const [isTransforming, setIsTransforming] = useState(false);
  const [liveDimensions, setLiveDimensions] = useState<{ w: number, d: number, h: number } | null>(null);
  const baseDimensions = useMemo(() => getBaseDimensions(shape.points), [shape.points]);

  const [dragHandle, setDragHandle] = useState<{ axis: 'x' | 'z', direction: 1 | -1, startPoint: THREE.Vector3, anchorPointWorld: THREE.Vector3, startScale: THREE.Vector3 } | null>(null);

  const geometry = useMemo(() => {
    if (!threeShape || shape.type === 'dimension') return null;
    return new THREE.ExtrudeGeometry(threeShape, { depth: shape.height, bevelEnabled: false });
  }, [threeShape, shape.height, shape.type]);

  useEffect(() => {
    if (groupRef.current) {
        groupRef.current.position.set(shape.position[0], shape.position[1], shape.position[2]);
        groupRef.current.rotation.set(0, shape.rotation, 0); 
        groupRef.current.scale.set(shape.scale[0], shape.scale[1], shape.scale[2]);
    }
  }, [shape.position, shape.rotation, shape.scale]);

  const onHandleDragStart = (e: ThreeEvent<PointerEvent>, axis: 'x' | 'z', direction: 1 | -1) => {
      if (!groupRef.current) return;

      const point = e.point.clone(); 
      const target = groupRef.current;

      const { minX, maxX, minZ, maxZ, centerX, centerZ } = baseDimensions;

      let localAnchor: THREE.Vector3;
      if (axis === 'x') {
          const anchorX = direction === 1 ? minX : maxX;
          localAnchor = new THREE.Vector3(anchorX, 0, centerZ);
      } else {
          const anchorZ = direction === 1 ? minZ : maxZ;
          localAnchor = new THREE.Vector3(centerX, 0, anchorZ);
      }

      target.updateMatrixWorld();
      const anchorPointWorld = localAnchor.clone().applyMatrix4(target.matrixWorld);

      setDragHandle({
          axis,
          direction,
          startPoint: point,
          anchorPointWorld,
          startScale: target.scale.clone(),
      });
      setIsTransforming(true);

      const onPointerMove = (moveEvent: PointerEvent) => {
        if (!groupRef.current) return;

        const ndc = new THREE.Vector2(
             (moveEvent.clientX / window.innerWidth) * 2 - 1,
            -(moveEvent.clientY / window.innerHeight) * 2 + 1
        );
        raycaster.setFromCamera(ndc, camera);
        const plane = new THREE.Plane(new THREE.Vector3(0, 1, 0), -shape.position[1]);
        const targetPoint = new THREE.Vector3();
        raycaster.ray.intersectPlane(plane, targetPoint);

        if (targetPoint) {
           handleResizeDrag(targetPoint);
        }
      };

      const onPointerUp = () => {
          window.removeEventListener('pointermove', onPointerMove);
          window.removeEventListener('pointerup', onPointerUp);

          setDragHandle(null);
          setIsTransforming(false);
          setLiveDimensions(null);

          if (groupRef.current) {
              updateShape(shape.id, {
                  scale: [groupRef.current.scale.x, groupRef.current.scale.y, groupRef.current.scale.z],
                  position: [groupRef.current.position.x, groupRef.current.position.y, groupRef.current.position.z]
              });
          }
      };

      window.addEventListener('pointermove', onPointerMove);
      window.addEventListener('pointerup', onPointerUp);
  };

  const handleResizeDrag = (currentPoint: THREE.Vector3) => {
      if (!dragHandle || !groupRef.current) return;

      const { axis, direction, startPoint, startScale, anchorPointWorld } = dragHandle;
      const target = groupRef.current;

      const deltaWorld = currentPoint.clone().sub(startPoint);
      const rotationY = shape.rotation;
      const deltaLocal = deltaWorld.clone().applyAxisAngle(new THREE.Vector3(0, 1, 0), -rotationY);

      const change = axis === 'x' ? deltaLocal.x : deltaLocal.z;
      const baseSize = axis === 'x' ? baseDimensions.width : baseDimensions.depth;
      if (baseSize < 0.001) return;

      const scaleChange = (change * direction) / baseSize;

      let newScaleValue = (axis === 'x' ? startScale.x : startScale.z) + scaleChange;
      if (newScaleValue < 0.01) newScaleValue = 0.01;

      const newScale = startScale.clone();
      if (axis === 'x') newScale.x = newScaleValue;
      else newScale.z = newScaleValue;

      target.scale.copy(newScale);
      target.updateMatrixWorld();

      const { minX, maxX, minZ, maxZ, centerX, centerZ } = baseDimensions;
      let localAnchor: THREE.Vector3;
      if (axis === 'x') {
          const anchorX = direction === 1 ? minX : maxX;
          localAnchor = new THREE.Vector3(anchorX, 0, centerZ);
      } else {
          const anchorZ = direction === 1 ? minZ : maxZ;
          localAnchor = new THREE.Vector3(centerX, 0, anchorZ);
      }

      const currentAnchorWorld = localAnchor.clone().applyMatrix4(target.matrixWorld);

      const shift = anchorPointWorld.clone().sub(currentAnchorWorld);
      target.position.add(shift);

      setLiveDimensions({
          w: baseDimensions.width * newScale.x,
          d: baseDimensions.depth * newScale.z,
          h: shape.height * startScale.y
      });
  };

  const handleDragStart = () => {
    setIsTransforming(true);
    const others = shapes.filter(s => s.id !== shape.id);
    let allPoints: SnapPoint[] = [];
    others.forEach(s => {
        allPoints = [...allPoints, ...getSnapCandidates(s)];
    });
    targetSnapPointsRef.current = allPoints;
    setActiveSnap(null);
  };

  const handleDragEnd = () => {
    setIsTransforming(false);
    setLiveDimensions(null);
    if (groupRef.current) {
        updateShape(shape.id, {
            position: [groupRef.current.position.x, groupRef.current.position.y, groupRef.current.position.z],
            rotation: groupRef.current.rotation.y,
            scale: [groupRef.current.scale.x, groupRef.current.scale.y, groupRef.current.scale.z]
        });
    }
    targetSnapPointsRef.current = [];
    setActiveSnap(null);
  };

  const handleObjectChange = (e: any) => {
      if (!groupRef.current) return;
      const target = groupRef.current;

      if (transformMode === 'scale') {
          const s = target.scale;
          setLiveDimensions({
              w: baseDimensions.width * s.x,
              d: baseDimensions.depth * s.z,
              h: shape.height * s.y
          });
          return;
      }

      if (transformMode !== 'translate') return;

      target.updateMatrixWorld();
      const mat = target.matrixWorld;
      let currentPoints: { local: THREE.Vector3, world: THREE.Vector3 }[] = [];

      if (shape.type !== 'dimension') {
          const { centerX, centerZ } = baseDimensions;
          const centerBot = new THREE.Vector3(centerX, 0, centerZ);
          currentPoints.push({ local: centerBot.clone(), world: centerBot.applyMatrix4(mat).clone() });

          shape.points.forEach(p => {
              const vBot = new THREE.Vector3(p.x, 0, p.z);
              currentPoints.push({ local: vBot.clone(), world: vBot.applyMatrix4(mat).clone() });
          });
      }

      let bestDist = 0.3; 
      let snapMatch: { sourceLocal: THREE.Vector3, targetWorld: THREE.Vector3 } | null = null;

      for (const source of currentPoints) {
          for (const targetPt of targetSnapPointsRef.current) {
              const dist = source.world.distanceTo(targetPt.pos);
              if (dist < bestDist) {
                  bestDist = dist;
                  snapMatch = { sourceLocal: source.local, targetWorld: targetPt.pos };
              }
          }
      }

      if (snapMatch) {
          const offset = snapMatch.sourceLocal.clone()
             .applyEuler(target.rotation)
             .multiply(target.scale);

          const newPos = snapMatch.targetWorld.clone().sub(offset);
          target.position.copy(newPos);

          const startVec = newPos.clone().add(offset);
          const endVec = snapMatch.targetWorld;

          setActiveSnap({ 
              start: [startVec.x, startVec.y, startVec.z], 
              end: [endVec.x, endVec.y, endVec.z] 
          });
      } else {
          setActiveSnap(null);
          if (Math.abs(target.position.y) < 0.1) {
              target.position.y = 0;
          }
      }
  };

  const handleHeightChange = (e: any) => {
    if (e.target.object) {
      const newHeight = e.target.object.position.y;
      if (newHeight > 0.01) {
        const isNowSolid = newHeight > 0.1;
        updateShape(shape.id, { 
          height: newHeight,
          type: isNowSolid ? 'solid' : 'flat',
          color: isNowSolid && shape.color === FLAT_COLOR ? DEFAULT_COLOR : shape.color
        });
      }
    }
  };

  if (shape.type === 'dimension') {
      const p1 = shape.points[0];
      const p2 = shape.points[1];
      const dist = Math.sqrt(Math.pow(p2.x - p1.x, 2) + Math.pow(p2.z - p1.z, 2) + Math.pow(p2.y - p1.y, 2));
      const midX = (p1.x + p2.x) / 2;
      const midY = (p1.y + p2.y) / 2 + 0.1;
      const midZ = (p1.z + p2.z) / 2;

      return (
        <group 
            ref={groupRef}
            userData={{ isShape: true, id: shape.id }}
            onClick={(e) => {
                if (tool === ToolType.SELECT) {
                    e.stopPropagation();
                    setSelectedId(shape.id);
                }
            }}
        >
            <Line 
                points={[[p1.x, p1.y + 0.05, p1.z], [p2.x, p2.y + 0.05, p2.z]]} 
                color={isSelected ? HIGHLIGHT_COLOR : shape.color} 
                lineWidth={3} 
                dashed 
                dashScale={10}
            />
            <mesh position={[p1.x, p1.y + 0.05, p1.z]}>
                <sphereGeometry args={[0.06]} />
                <meshBasicMaterial color={isSelected ? HIGHLIGHT_COLOR : shape.color} />
            </mesh>
            <mesh position={[p2.x, p2.y + 0.05, p2.z]}>
                <sphereGeometry args={[0.06]} />
                <meshBasicMaterial color={isSelected ? HIGHLIGHT_COLOR : shape.color} />
            </mesh>
            <Html position={[midX, midY, midZ]} center style={{ pointerEvents: 'none' }}>
                <div 
                    className={`text-xs px-2 py-1 rounded whitespace-nowrap backdrop-blur-sm border ${
                        isSelected 
                        ? 'bg-blue-600/90 text-white border-blue-400' 
                        : 'bg-black/70 text-yellow-400 border-yellow-500/50'
                    }`}
                >
                    {formatValue(dist)}
                </div>
            </Html>
        </group>
      );
  }

  const { minX, maxX, minZ, maxZ, centerX, centerZ } = baseDimensions;
  const hPos = shape.height / 2;
  const offset = 0.4; 

  return (
    <>
      {isSelected && tool === ToolType.SELECT && (
        <TransformControls
            object={groupRef}
            mode={transformMode === 'scale' ? 'scale' : 'translate'}
            enabled={transformMode === 'translate'}
            showY={true} showX={true} showZ={true}
            onMouseDown={handleDragStart}
            onMouseUp={handleDragEnd}
            onObjectChange={handleObjectChange}
        />
      )}

      {isSelected && activeSnap && <SnapIndicator start={activeSnap.start} end={activeSnap.end} />}

      {isSelected && isTransforming && liveDimensions && (
         <Html position={[0, shape.height + 0.5, 0]} center style={{ pointerEvents: 'none' }}>
            <div className="flex flex-col gap-1 bg-black/80 text-white text-xs p-2 rounded backdrop-blur-sm border border-white/20 shadow-xl z-50">
               <div className="flex justify-between gap-3"><span>寬(W):</span> <span className="font-mono text-blue-300">{formatValue(liveDimensions.w)}</span></div>
               <div className="flex justify-between gap-3"><span>深(D):</span> <span className="font-mono text-green-300">{formatValue(liveDimensions.d)}</span></div>
               <div className="flex justify-between gap-3"><span>高(H):</span> <span className="font-mono text-yellow-300">{formatValue(liveDimensions.h)}</span></div>
            </div>
         </Html>
      )}

      {isSelected && tool === ToolType.SELECT && (
        <TransformControls
            mode="translate"
            position={[shape.position[0], shape.height, shape.position[2]]} 
            showX={false} showZ={false} showY={true}
            translationSnap={0.05}
            onObjectChange={handleHeightChange}
        >
            <mesh>
              <boxGeometry args={[0.3, 0.3, 0.3]} />
              <meshBasicMaterial color="#4ade80" depthTest={false} transparent opacity={0.8} />
            </mesh>
            <Html position={[0.4, 0, 0]} center style={{ pointerEvents: 'none' }}>
                <div className="bg-green-500 text-white text-xs px-1 rounded font-mono shadow-md whitespace-nowrap">
                    H: {formatValue(shape.height)}
                </div>
            </Html>
        </TransformControls>
      )}

      <group 
        ref={groupRef}
        userData={{ isShape: true, id: shape.id }}
        onClick={(e) => {
          if (tool === ToolType.SELECT) {
            e.stopPropagation();
            setSelectedId(shape.id);
          }
        }}
      >
        <mesh rotation={[-Math.PI / 2, 0, 0]}>
            <primitive object={geometry} attach="geometry" />
            <meshStandardMaterial 
              color={isSelected ? HIGHLIGHT_COLOR : shape.color} 
              transparent={isSelected || shape.type === 'flat'} 
              opacity={shape.type === 'flat' ? 0.6 : (isSelected ? 0.9 : 1)}
              side={THREE.DoubleSide}
            />
            {isSelected && (
              <lineSegments>
                <edgesGeometry args={[geometry]} />
                <lineBasicMaterial color="white" />
              </lineSegments>
            )}
        </mesh>

        {/* --- Custom Smart Resize Gizmos --- */}
        {isSelected && tool === ToolType.SELECT && (
            <group>
                {/* 
                  Note on offsets:
                  The handles are children of the scaled group. 
                  Therefore, a fixed world offset (e.g. 0.4m) must be divided by the scale to result in the correct local position.
                  pos = minX + (offset / scaleX)
                */}
                <ResizeHandle 
                    position={[maxX + offset / shape.scale[0], hPos, centerZ]} 
                    parentScale={shape.scale}
                    axis="x" 
                    direction={1} 
                    onDragStart={onHandleDragStart} 
                    color="#ef4444"
                />
                 <ResizeHandle 
                    position={[minX - offset / shape.scale[0], hPos, centerZ]} 
                    parentScale={shape.scale}
                    axis="x" 
                    direction={-1} 
                    onDragStart={onHandleDragStart} 
                    color="#ef4444" 
                />
                 <ResizeHandle 
                    position={[centerX, hPos, maxZ + offset / shape.scale[2]]} 
                    parentScale={shape.scale}
                    axis="z" 
                    direction={1} 
                    onDragStart={onHandleDragStart} 
                    color="#3b82f6"
                />
                 <ResizeHandle 
                    position={[centerX, hPos, minZ - offset / shape.scale[2]]} 
                    parentScale={shape.scale}
                    axis="z" 
                    direction={-1} 
                    onDragStart={onHandleDragStart} 
                    color="#3b82f6"
                />
            </group>
        )}
      </group>
    </>
  );
};

