};

const DrawingManager: React.FC = () => {
  const { tool, addShape, formatValue } = useApp();
  const [startPoint, setStartPoint] = useState<IPoint | null>(null);
  const [currentPoint, setCurrentPoint] = useState<IPoint | null>(null);
  const [polyPoints, setPolyPoints] = useState<IPoint[]>([]);
  const [measureStart, setMeasureStart] = useState<IPoint | null>(null);
  const [measureEnd, setMeasureEnd] = useState<IPoint | null>(null);
  const { raycaster, scene, camera } = useThree();

  useEffect(() => {
    setStartPoint(null);
    setCurrentPoint(null);
    setPolyPoints([]);
    setMeasureStart(null);
    setMeasureEnd(null);
  }, [tool]);

  useFrame(({ pointer }) => {
    if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) {
        if (currentPoint) setCurrentPoint(null);
        return;
    }

    raycaster.setFromCamera(pointer, camera);
    const interactables = scene.children.filter(obj => 
        obj.name === 'ground_plane' || 
        obj.userData?.isShape
    );
    const intersects = raycaster.intersectObjects(interactables, true);
    let hitPoint: THREE.Vector3 | null = null;

    for (const hit of intersects) {
        if (hit.object.name === 'cursor_helper' || hit.object.name === 'preview_helper') continue;
        if (hit.object.name === 'ground_plane') {
            hitPoint = hit.point;
            break;
        }
        let obj: THREE.Object3D | null = hit.object;
        let isShape = false;
        while(obj) {
            if (obj.userData?.isShape) {
                isShape = true;
                break;
            }
            obj = obj.parent;
        }
        if (isShape) {
            hitPoint = hit.point;
            break;
        }
    }

    if (hitPoint) {
        const x = Math.round(hitPoint.x / SNAP_GRID) * SNAP_GRID;
        const z = Math.round(hitPoint.z / SNAP_GRID) * SNAP_GRID;
        let y = hitPoint.y;
        if (y < 0.05) y = 0;

        if (!currentPoint || 
            Math.abs(currentPoint.x - x) > 0.001 || 
            Math.abs(currentPoint.z - z) > 0.001 || 
            Math.abs(currentPoint.y - y) > 0.001) {
            setCurrentPoint({ x, y, z });
        }
    } else {
        if (currentPoint) setCurrentPoint(null);
    }
  });

  const handleClick = (e: ThreeEvent<MouseEvent>) => {
    if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL || !currentPoint) return;
    e.stopPropagation();
    const p = { ...currentPoint };

    if (tool === ToolType.MEASURE) {
        if (!measureStart) {
            setMeasureStart(p);
            setMeasureEnd(null);
        } else {
            const dist = Math.sqrt(Math.pow(p.x - measureStart.x, 2) + Math.pow(p.z - measureStart.z, 2));
            if (dist > 0.01) {
                addShape({
                    id: `dim-${Date.now()}`,
                    name: '尺寸標註',
                    type: 'dimension',
                    points: [measureStart, p], 
                    height: 0,
                    color: DIMENSION_COLOR,
                    position: [0, 0, 0],
                    rotation: 0,
                    scale: [1, 1, 1]
                });
            }
            setMeasureStart(null);
            setMeasureEnd(null);
        }
        return;
    }

    if (tool === ToolType.DRAW_POLY) {
      if (polyPoints.length > 2) {
         const start = polyPoints[0];
         const dist = Math.sqrt(Math.pow(p.x - start.x, 2) + Math.pow(p.z - start.z, 2));
         if (dist < 0.5) {
           finishShape(polyPoints);
           return;
         }
      }
      setPolyPoints([...polyPoints, p]);
    } else {
      if (!startPoint) {
        setStartPoint(p);
      } else {
        finishPrimitive(startPoint, p);
      }
    }
  };

  const finishPrimitive = (start: IPoint, end: IPoint) => {
    let points: IPoint[] = [];
    let name = "平面";
    const cx = (start.x + end.x) / 2;
    const cz = (start.z + end.z) / 2;
    const dx = end.x - start.x;
    const dz = end.z - start.z;
    const dist = Math.sqrt(dx*dx + dz*dz);

    if (dist < 0.1) return;
    let finalPos: [number, number, number] = [0,0,0];

    switch (tool) {
      case ToolType.DRAW_LINE:
        const thickness = 0.2; 
        const len = dist;
        points = [
          { x: 0, y: 0, z: -thickness/2 },
          { x: len, y: 0, z: -thickness/2 },
          { x: len, y: 0, z: thickness/2 },
          { x: 0, y: 0, z: thickness/2 },
          { x: 0, y: 0, z: -thickness/2 }
        ];
        finalPos = [start.x, start.y, start.z]; 
        name = "牆面";
        break;

      case ToolType.DRAW_RECT:
        const w = Math.abs(dx);
        const d = Math.abs(dz);
        finalPos = [cx, start.y, cz];
        points = [
          { x: -w/2, y: 0, z: -d/2 },
          { x: w/2, y: 0, z: -d/2 },
          { x: w/2, y: 0, z: d/2 },
          { x: -w/2, y: 0, z: d/2 },
          { x: -w/2, y: 0, z: -d/2 }
        ];
        name = "區域";
        break;

      case ToolType.DRAW_CIRCLE:
        finalPos = [start.x, start.y, start.z];
        points = createCirclePoints(dist);
        name = "圓形";
        break;

      case ToolType.DRAW_ARC:
        finalPos = [start.x, start.y, start.z];
        points = createArcPoints(dist);
        name = "開門";
        break;
    }

    let rotation = 0;
    if (tool === ToolType.DRAW_LINE || tool === ToolType.DRAW_ARC) {
       rotation = -Math.atan2(dz, dx); 
    }

    addShape({
      id: `shape-${Date.now()}`,
      name: `${name}`,
      type: 'flat',
      points,
      height: DEFAULT_HEIGHT,
      color: FLAT_COLOR,
      position: finalPos,
      rotation: rotation,
      scale: [1, 1, 1]
    });
    setStartPoint(null);
  };

  const finishShape = (pts: IPoint[]) => {
    if (pts.length < 3) return;
    const cx = pts.reduce((sum, p) => sum + p.x, 0) / pts.length;
    const cz = pts.reduce((sum, p) => sum + p.z, 0) / pts.length;
    const cy = pts[0].y;

    const centeredPoints = pts.map(p => ({ x: p.x - cx, y: 0, z: p.z - cz }));
    centeredPoints.push(centeredPoints[0]);

    addShape({
      id: `poly-${Date.now()}`,
      name: `多邊形`,
      type: 'flat',
      points: centeredPoints,
      height: DEFAULT_HEIGHT,
      color: FLAT_COLOR,
      position: [cx, cy, cz],
      rotation: 0,
      scale: [1, 1, 1]
    });
    setPolyPoints([]);
    setStartPoint(null);
  };

  const previewPoints = useMemo(() => {
     if (tool === ToolType.DRAW_POLY) {
        if (polyPoints.length === 0 && !currentPoint) return [];
        const pts = [...polyPoints];
        if (currentPoint) pts.push(currentPoint);
        return pts;
     }

     if (startPoint && currentPoint) {
         if (tool === ToolType.DRAW_LINE) {
             const thickness = 0.2;
             const dx = currentPoint.x - startPoint.x;
             const dz = currentPoint.z - startPoint.z;
             const len = Math.sqrt(dx*dx + dz*dz);
             if (len < 0.01) return [startPoint, currentPoint];
             const nx = -dz / len;
             const nz = dx / len;
             const ox = nx * (thickness / 2);
             const oz = nz * (thickness / 2);
             return [
               { x: startPoint.x + ox, y: 0, z: startPoint.z + oz },
               { x: currentPoint.x + ox, y: 0, z: currentPoint.z + oz },
               { x: currentPoint.x - ox, y: 0, z: currentPoint.z - oz },
               { x: startPoint.x - ox, y: 0, z: startPoint.z - oz },
               { x: startPoint.x + ox, y: 0, z: startPoint.z + oz },
             ];
         }
         if (tool === ToolType.DRAW_RECT) {
             return [
                 startPoint,
                 { x: currentPoint.x, y: 0, z: startPoint.z },
                 currentPoint,
                 { x: startPoint.x, y: 0, z: currentPoint.z },
                 startPoint
             ];
         }
         if (tool === ToolType.DRAW_CIRCLE || tool === ToolType.DRAW_ARC) {
             const dist = Math.sqrt(Math.pow(currentPoint.x - startPoint.x, 2) + Math.pow(currentPoint.z - startPoint.z, 2));
             const func = tool === ToolType.DRAW_CIRCLE ? createCirclePoints : createArcPoints;
             const seg = tool === ToolType.DRAW_CIRCLE ? 64 : 32;
             return func(dist, seg).map(p => ({
                 x: p.x + startPoint.x,
                 y: 0,
                 z: p.z + startPoint.z
             }));
         }
     }
     return [];
  }, [tool, startPoint, currentPoint, polyPoints]);

  const drawY = useMemo(() => {
    if (startPoint) return startPoint.y;
    if (polyPoints.length > 0) return polyPoints[0].y;
    if (currentPoint) return currentPoint.y;
    return 0;
  }, [startPoint, polyPoints, currentPoint]);

  return (
    <>
      <mesh 
        name="ground_plane"
        rotation={[-Math.PI / 2, 0, 0]} 
        position={[0, -0.01, 0]} 
        onClick={handleClick}
      >
        <planeGeometry args={[100, 100]} />
        <meshBasicMaterial color="black" transparent opacity={0} />
      </mesh>

      {currentPoint && tool !== ToolType.SELECT && tool !== ToolType.PUSH_PULL && (
        <mesh name="cursor_helper" position={[currentPoint.x, currentPoint.y + 0.05, currentPoint.z]} rotation={[-Math.PI / 2, 0, 0]}>
          <ringGeometry args={[0.1, 0.15, 32]} />
          <meshBasicMaterial color="#ef4444" depthTest={false} />
        </mesh>
      )}

      {tool === ToolType.MEASURE && measureStart && (
        <>
            <Line 
                points={[
                    [measureStart.x, measureStart.y + 0.05, measureStart.z],
                    (() => {
                        const target = measureEnd || currentPoint || measureStart;
                        return [target.x, target.y + 0.05, target.z] as [number, number, number];
                    })()
                ]} 
                color="#facc15" 
                lineWidth={2} 
                dashed 
                dashScale={50}
                depthTest={false}
            />
            {/* ... dots and tooltips ... */}
             <mesh position={[measureStart.x, measureStart.y, measureStart.z]}>
                <sphereGeometry args={[0.08]} />
                <meshBasicMaterial color="#facc15" depthTest={false} />
            </mesh>
            {(measureEnd || currentPoint) && (
                <mesh position={(() => {
                    const p = measureEnd || currentPoint;
                    return p ? [p.x, p.y, p.z] : [0,0,0];
                })()}>
                    <sphereGeometry args={[0.08]} />
                    <meshBasicMaterial color="#facc15" depthTest={false} />
                </mesh>
            )}
             <CursorTooltip 
                position={(() => {
                    const target = measureEnd || currentPoint || measureStart;
                    return [
                        (measureStart.x + target.x) / 2,
                        measureStart.y + 0.5,
                        (measureStart.z + target.z) / 2
                    ] as [number, number, number];
                })()}
                text={(() => {
                    const target = measureEnd || currentPoint || measureStart;
                    const dist = Math.sqrt(
                        Math.pow(target.x - measureStart.x, 2) + 
                        Math.pow(target.z - measureStart.z, 2) +
                        Math.pow(target.y - measureStart.y, 2)
                    );
                    return `距離: ${formatValue(dist)}`;
                })()}
            />
        </>
      )}

      {previewPoints.length > 0 && (startPoint || polyPoints.length > 0) && (
         <PreviewFill points={previewPoints} y={drawY} />
      )}

      {previewPoints.length > 1 && (
        <Line 
           name="preview_helper"
           points={previewPoints.map(p => [p.x, drawY + 0.06, p.z] as [number, number, number])}
           color="#38bdf8"
           lineWidth={2}
           transparent
           opacity={0.8}
        />
      )}
    </>
  );
};

const RenderedShape: React.FC<{ shape: IShape }> = ({ shape }) => {
  const { selectedId, setSelectedId, tool, updateShape, formatValue } = useApp();
  const isSelected = selectedId === shape.id;
  const groupRef = useRef<THREE.Group>(null);

  const threeShape = useMemo(() => {
    if (shape.type === 'dimension') return null;
    return createThreeShape(shape.points);
  }, [shape.points, shape.type]);

  const baseDimensions = useMemo(() => getBaseDimensions(shape.points), [shape.points]);

  const geometry = useMemo(() => {
    if (!threeShape || shape.type === 'dimension') return null;
    return new THREE.ExtrudeGeometry(threeShape, { depth: shape.height, bevelEnabled: false });
  }, [threeShape, shape.height, shape.type]);

  useEffect(() => {
    if (groupRef.current) {
        groupRef.current.position.set(shape.position[0], shape.position[1], shape.position[2]);
        groupRef.current.rotation.set(0, shape.rotation, 0); 
        groupRef.current.scale.set(shape.scale[0], shape.scale[1], shape.scale[2]);
    }
  }, [shape.position, shape.rotation, shape.scale]);

  // Handle updates from TransformControls
  const handleTransformChange = (e: any) => {
      if (!groupRef.current) return;
      // When standard translate/rotate happens in SELECT mode
      updateShape(shape.id, {
        position: [groupRef.current.position.x, groupRef.current.position.y, groupRef.current.position.z],
        rotation: groupRef.current.rotation.y,
        scale: [groupRef.current.scale.x, groupRef.current.scale.y, groupRef.current.scale.z]
      });
  };

  const handleHeightChange = (e: any) => {
    if (e.target.object) {
      const newHeight = e.target.object.position.y;
      if (newHeight > 0.01) {
         updateShape(shape.id, { height: newHeight, type: newHeight > 0.1 ? 'solid' : 'flat' });
      }
    }
  };

  const handleWidthChange = (e: any) => {
      if (!e.target.object) return;
      // We moved a dummy object in X axis. 
      // Current X position relative to origin (center) determines scale.
      const currentX = e.target.object.position.x;
      const baseWidth = baseDimensions.maxX; // since we put anchor at maxX
      // Only support uniform scaling for this side for now or basic stretch
      // Scale = currentX / baseWidth (relative to local center)
      if (baseWidth === 0) return;
      let newScaleX = currentX / baseWidth;
      if (newScaleX < 0.1) newScaleX = 0.1;
      updateShape(shape.id, { scale: [newScaleX, shape.scale[1], shape.scale[2]] });
  };

  const handleDepthChange = (e: any) => {
      if (!e.target.object) return;
      const currentZ = e.target.object.position.z;
      const baseDepth = baseDimensions.maxZ; 
      if (baseDepth === 0) return;
      let newScaleZ = currentZ / baseDepth;
      if (newScaleZ < 0.1) newScaleZ = 0.1;
      updateShape(shape.id, { scale: [shape.scale[0], shape.scale[1], newScaleZ] });
  };

  if (shape.type === 'dimension') {
      const p1 = shape.points[0];
      const p2 = shape.points[1];
      const dist = Math.sqrt(Math.pow(p2.x - p1.x, 2) + Math.pow(p2.z - p1.z, 2) + Math.pow(p2.y - p1.y, 2));
      const midX = (p1.x + p2.x) / 2;
      const midY = (p1.y + p2.y) / 2 + 0.1;
      const midZ = (p1.z + p2.z) / 2;
      return (
        <group 
            ref={groupRef}
            userData={{ isShape: true, id: shape.id }}
            onClick={(e) => {
                if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) {
                    e.stopPropagation();
                    setSelectedId(shape.id);
                }
            }}
        >
            <Line points={[[p1.x, p1.y+0.05, p1.z], [p2.x, p2.y+0.05, p2.z]]} color={isSelected ? HIGHLIGHT_COLOR : shape.color} lineWidth={3} dashed dashScale={10} />
            <mesh position={[p1.x, p1.y+0.05, p1.z]}><sphereGeometry args={[0.06]} /><meshBasicMaterial color={isSelected ? HIGHLIGHT_COLOR : shape.color} /></mesh>
            <mesh position={[p2.x, p2.y+0.05, p2.z]}><sphereGeometry args={[0.06]} /><meshBasicMaterial color={isSelected ? HIGHLIGHT_COLOR : shape.color} /></mesh>
            <Html position={[midX, midY, midZ]} center style={{ pointerEvents: 'none' }}>
                <div className={`text-xs px-2 py-1 rounded whitespace-nowrap backdrop-blur-sm border ${isSelected ? 'bg-blue-600/90 text-white border-blue-400' : 'bg-black/70 text-yellow-400 border-yellow-500/50'}`}>
                    {formatValue(dist)}
                </div>
            </Html>
        </group>
      );
  }

  const { maxX, maxZ, centerX, centerZ } = baseDimensions;

  return (
    <>
      {/* --- Standard Move/Rotate Controls (Only in SELECT mode) --- */}
      {isSelected && tool === ToolType.SELECT && (
        <TransformControls
            object={groupRef}
            mode="translate" // Allows switching to rotate if we added mode switching, but sticking to translate for Select tool base
            showY={true} showX={true} showZ={true}
            onMouseUp={handleTransformChange}
        />
      )}

      {/* --- Push/Pull Resize Controls (Only in PUSH_PULL mode) --- */}
      {isSelected && tool === ToolType.PUSH_PULL && (
        <>
           {/* Height Control (Green Arrow - Top Center) */}
            <TransformControls
                mode="translate"
                position={[shape.position[0], shape.height, shape.position[2]]} 
                showX={false} showZ={false} showY={true}
                translationSnap={0.05}
                onObjectChange={handleHeightChange}
            >
                <mesh>
                   <boxGeometry args={[0.2, 0.2, 0.2]} />
                   <meshBasicMaterial color="#4ade80" depthTest={false} transparent opacity={0.8} />
                </mesh>
                <Html position={[0.4, 0, 0]} center style={{ pointerEvents: 'none' }}>
                    <div className="bg-green-600 text-white text-xs px-1 rounded font-mono shadow-md whitespace-nowrap">H</div>
                </Html>
            </TransformControls>

            {/* Width Control (Red Arrow - Right Edge) */}
            <TransformControls
                mode="translate"
                // Position relative to object center roughly, but we need world coords.
                // We attach to a dummy object at the edge.
                // Note: TransformControls attaches to 'object', or we can put it in the scene and control a dummy.
                // A simpler way with Drei is to position the TransformControl at the handle location.
                position={[
                    shape.position[0] + (maxX * shape.scale[0] * Math.cos(shape.rotation)) - (centerZ * Math.sin(shape.rotation)),
                    shape.position[1] + shape.height / 2,
                    shape.position[2] + (maxX * shape.scale[0] * Math.sin(shape.rotation)) + (centerZ * Math.cos(shape.rotation))
                ]}
                rotation={[0, shape.rotation, 0]}
                showX={true} showY={false} showZ={false}
                onObjectChange={handleWidthChange}
            >
                <mesh>
                   <boxGeometry args={[0.2, 0.2, 0.2]} />
                   <meshBasicMaterial color="#f87171" depthTest={false} transparent opacity={0.8} />
                </mesh>
                <Html position={[0, 0.4, 0]} center style={{ pointerEvents: 'none' }}>
                    <div className="bg-red-500 text-white text-xs px-1 rounded font-mono shadow-md whitespace-nowrap">W</div>
                </Html>
            </TransformControls>

             {/* Depth Control (Blue Arrow - Front Edge) */}
             <TransformControls
                mode="translate"
                position={[
                    shape.position[0] + (centerX * Math.cos(shape.rotation)) - (maxZ * shape.scale[2] * Math.sin(shape.rotation)),
                    shape.position[1] + shape.height / 2,
                    shape.position[2] + (centerX * Math.sin(shape.rotation)) + (maxZ * shape.scale[2] * Math.cos(shape.rotation))
                ]}
                rotation={[0, shape.rotation, 0]}
                showX={false} showY={false} showZ={true}
                onObjectChange={handleDepthChange}
            >
                 <mesh>
                   <boxGeometry args={[0.2, 0.2, 0.2]} />
                   <meshBasicMaterial color="#60a5fa" depthTest={false} transparent opacity={0.8} />
                </mesh>
                <Html position={[0, 0.4, 0]} center style={{ pointerEvents: 'none' }}>
                    <div className="bg-blue-500 text-white text-xs px-1 rounded font-mono shadow-md whitespace-nowrap">D</div>
                </Html>
            </TransformControls>
        </>
      )}

      <group 
        ref={groupRef}
        userData={{ isShape: true, id: shape.id }}
        onClick={(e) => {
          if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) {
            e.stopPropagation();
            setSelectedId(shape.id);
          }
        }}
      >
        <mesh rotation={[-Math.PI / 2, 0, 0]}>
            <primitive object={geometry} attach="geometry" />
            <meshStandardMaterial 
              color={isSelected ? HIGHLIGHT_COLOR : shape.color} 
              transparent={isSelected || shape.type === 'flat'} 
              opacity={shape.type === 'flat' ? 0.6 : (isSelected ? 0.9 : 1)}
              side={THREE.DoubleSide}
            />
            {isSelected && (
              <lineSegments>
                <edgesGeometry args={[geometry]} />
                <lineBasicMaterial color="white" />
              </lineSegments>
            )}
        </mesh>
      </group>
    </>
  );
};

import React, { useRef, useState, useMemo, useEffect } from 'react';
import { Canvas, useThree, ThreeEvent, useFrame } from '@react-three/fiber';
import { OrbitControls, Grid, Environment, TransformControls, Html, Line, GizmoHelper, GizmoViewport } from '@react-three/drei';
import * as THREE from 'three';
import { useApp } from '../context/AppContext';
import { ToolType, IPoint, IShape, ShapeType } from '../types';
import { SNAP_GRID, DEFAULT_COLOR, FLAT_COLOR, HIGHLIGHT_COLOR, DIMENSION_COLOR, DEFAULT_HEIGHT } from '../constants';

// --- Types for Snapping ---
interface SnapPoint {
    pos: THREE.Vector3;
    type: 'vertex' | 'center' | 'midpoint';
}

// --- Helpers ---
const createThreeShape = (points: IPoint[]) => {
  const shape = new THREE.Shape();
  if (!points || points.length === 0) return shape;

  if (points[0]) {
    shape.moveTo(points[0].x, -points[0].z); 
    for (let i = 1; i < points.length; i++) {
        if (points[i]) {
            shape.lineTo(points[i].x, -points[i].z);
        }
    }
  }
  shape.closePath();
  return shape;
};

const createCirclePoints = (radius: number, segments = 32): IPoint[] => {
  const points: IPoint[] = [];
  for (let i = 0; i < segments; i++) {
    const theta = (i / segments) * Math.PI * 2;
    points.push({ x: Math.cos(theta) * radius, y: 0, z: Math.sin(theta) * radius });
  }
  points.push(points[0]);
  return points;
};

const createArcPoints = (radius: number, segments = 16): IPoint[] => {
  const points: IPoint[] = [];
  points.push({ x: 0, y: 0, z: 0 });
  for (let i = 0; i <= segments; i++) {
    const theta = (i / segments) * (Math.PI / 2); 
    points.push({ x: Math.cos(theta) * radius, y: 0, z: Math.sin(theta) * radius });
  }
  points.push({ x: 0, y: 0, z: 0 });
  return points;
};

const getBaseDimensions = (points: IPoint[]) => {
    if (!points || points.length === 0) return { width: 0, depth: 0, minX: 0, maxX: 0, minZ: 0, maxZ: 0, centerX: 0, centerZ: 0 };
    let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity;
    points.forEach(p => {
        minX = Math.min(minX, p.x);
        maxX = Math.max(maxX, p.x);
        minZ = Math.min(minZ, p.z);
        maxZ = Math.max(maxZ, p.z);
    });
    return { 
        width: maxX - minX || 0.1, 
        depth: maxZ - minZ || 0.1,
        minX, maxX, minZ, maxZ,
        centerX: (minX + maxX) / 2,
        centerZ: (minZ + maxZ) / 2
    };
};

// --- Components ---

const CursorTooltip: React.FC<{ text: string; position: THREE.Vector3 | [number, number, number] }> = ({ text, position }) => {
  const pos = Array.isArray(position) ? position : [position.x, 0.5, position.z];
  return (
    <Html position={[pos[0], 0.5, pos[2]]} center style={{ pointerEvents: 'none' }}>
      <div className="bg-black/80 text-white text-xs px-2 py-1 rounded whitespace-nowrap backdrop-blur-sm border border-white/20">
        {text}
      </div>
    </Html>
  );
};

const PreviewFill: React.FC<{ points: IPoint[], y: number }> = ({ points, y }) => {
  const shape = useMemo(() => {
    if (!points || points.length < 3) return null;
    const s = new THREE.Shape();
    if (points[0]) {
      s.moveTo(points[0].x, -points[0].z);
      for (let i = 1; i < points.length; i++) {
        if (points[i]) {
            s.lineTo(points[i].x, -points[i].z);
        }
      }
    }
    s.closePath();
    return s;
  }, [points]);

  if (!shape) return null;

  return (
    <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, y + 0.02, 0]}>
      <shapeGeometry args={[shape]} />
      <meshBasicMaterial color="#38bdf8" transparent opacity={0.3} side={THREE.DoubleSide} depthTest={false} />
    </mesh>
  );
};

const DrawingManager: React.FC = () => {
  const { tool, addShape, formatValue } = useApp();
  const [startPoint, setStartPoint] = useState<IPoint | null>(null);
  const [currentPoint, setCurrentPoint] = useState<IPoint | null>(null);
  const [polyPoints, setPolyPoints] = useState<IPoint[]>([]);
  const [measureStart, setMeasureStart] = useState<IPoint | null>(null);
  const [measureEnd, setMeasureEnd] = useState<IPoint | null>(null);
  const { raycaster, scene, camera } = useThree();

  useEffect(() => {
    setStartPoint(null);
    setCurrentPoint(null);
    setPolyPoints([]);
    setMeasureStart(null);
    setMeasureEnd(null);
  }, [tool]);

  useFrame(({ pointer }) => {
    if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) {
        if (currentPoint) setCurrentPoint(null);
        return;
    }

    raycaster.setFromCamera(pointer, camera);
    const interactables = scene.children.filter(obj => 
        obj.name === 'ground_plane' || 
        obj.userData?.isShape
    );
    const intersects = raycaster.intersectObjects(interactables, true);
    let hitPoint: THREE.Vector3 | null = null;

    for (const hit of intersects) {
        if (hit.object.name === 'cursor_helper' || hit.object.name === 'preview_helper') continue;
        if (hit.object.name === 'ground_plane') {
            hitPoint = hit.point;
            break;
        }
        let obj: THREE.Object3D | null = hit.object;
        let isShape = false;
        while(obj) {
            if (obj.userData?.isShape) {
                isShape = true;
                break;
            }
            obj = obj.parent;
        }
        if (isShape) {
            hitPoint = hit.point;
            break;
        }
    }

    if (hitPoint) {
        const x = Math.round(hitPoint.x / SNAP_GRID) * SNAP_GRID;
        const z = Math.round(hitPoint.z / SNAP_GRID) * SNAP_GRID;
        let y = hitPoint.y;
        if (y < 0.05) y = 0;

        if (!currentPoint || 
            Math.abs(currentPoint.x - x) > 0.001 || 
            Math.abs(currentPoint.z - z) > 0.001 || 
            Math.abs(currentPoint.y - y) > 0.001) {
            setCurrentPoint({ x, y, z });
        }
    } else {
        if (currentPoint) setCurrentPoint(null);
    }
  });

  const handleClick = (e: ThreeEvent<MouseEvent>) => {
    if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL || !currentPoint) return;
    e.stopPropagation();
    const p = { ...currentPoint };

    if (tool === ToolType.MEASURE) {
        if (!measureStart) {
            setMeasureStart(p);
            setMeasureEnd(null);
        } else {
            const dist = Math.sqrt(Math.pow(p.x - measureStart.x, 2) + Math.pow(p.z - measureStart.z, 2));
            if (dist > 0.01) {
                addShape({
                    id: `dim-${Date.now()}`,
                    name: '尺寸標註',
                    type: 'dimension',
                    points: [measureStart, p], 
                    height: 0,
                    color: DIMENSION_COLOR,
                    position: [0, 0, 0],
                    rotation: 0,
                    scale: [1, 1, 1]
                });
            }
            setMeasureStart(null);
            setMeasureEnd(null);
        }
        return;
    }

    if (tool === ToolType.DRAW_POLY) {
      if (polyPoints.length > 2) {
         const start = polyPoints[0];
         const dist = Math.sqrt(Math.pow(p.x - start.x, 2) + Math.pow(p.z - start.z, 2));
         if (dist < 0.5) {
           finishShape(polyPoints);
           return;
         }
      }
      setPolyPoints([...polyPoints, p]);
    } else {
      if (!startPoint) {
        setStartPoint(p);
      } else {
        finishPrimitive(startPoint, p);
      }
    }
  };

  const finishPrimitive = (start: IPoint, end: IPoint) => {
    let points: IPoint[] = [];
    let name = "平面";
    const cx = (start.x + end.x) / 2;
    const cz = (start.z + end.z) / 2;
    const dx = end.x - start.x;
    const dz = end.z - start.z;
    const dist = Math.sqrt(dx*dx + dz*dz);

    if (dist < 0.1) return;
    let finalPos: [number, number, number] = [0,0,0];

    switch (tool) {
      case ToolType.DRAW_LINE:
        const thickness = 0.2; 
        const len = dist;
        points = [
          { x: 0, y: 0, z: -thickness/2 },
          { x: len, y: 0, z: -thickness/2 },
          { x: len, y: 0, z: thickness/2 },
          { x: 0, y: 0, z: thickness/2 },
          { x: 0, y: 0, z: -thickness/2 }
        ];
        finalPos = [start.x, start.y, start.z]; 
        name = "牆面";
        break;

      case ToolType.DRAW_RECT:
        const w = Math.abs(dx);
        const d = Math.abs(dz);
        finalPos = [cx, start.y, cz];
        points = [
          { x: -w/2, y: 0, z: -d/2 },
          { x: w/2, y: 0, z: -d/2 },
          { x: w/2, y: 0, z: d/2 },
          { x: -w/2, y: 0, z: d/2 },
          { x: -w/2, y: 0, z: -d/2 }
        ];
        name = "區域";
        break;

      case ToolType.DRAW_CIRCLE:
        finalPos = [start.x, start.y, start.z];
        points = createCirclePoints(dist);
        name = "圓形";
        break;

      case ToolType.DRAW_ARC:
        finalPos = [start.x, start.y, start.z];
        points = createArcPoints(dist);
        name = "開門";
        break;
    }

    let rotation = 0;
    if (tool === ToolType.DRAW_LINE || tool === ToolType.DRAW_ARC) {
       rotation = -Math.atan2(dz, dx); 
    }

    addShape({
      id: `shape-${Date.now()}`,
      name: `${name}`,
      type: 'flat',
      points,
      height: DEFAULT_HEIGHT,
      color: FLAT_COLOR,
      position: finalPos,
      rotation: rotation,
      scale: [1, 1, 1]
    });
    setStartPoint(null);
  };

  const finishShape = (pts: IPoint[]) => {
    if (pts.length < 3) return;
    const cx = pts.reduce((sum, p) => sum + p.x, 0) / pts.length;
    const cz = pts.reduce((sum, p) => sum + p.z, 0) / pts.length;
    const cy = pts[0].y;

    const centeredPoints = pts.map(p => ({ x: p.x - cx, y: 0, z: p.z - cz }));
    centeredPoints.push(centeredPoints[0]);

    addShape({
      id: `poly-${Date.now()}`,
      name: `多邊形`,
      type: 'flat',
      points: centeredPoints,
      height: DEFAULT_HEIGHT,
      color: FLAT_COLOR,
      position: [cx, cy, cz],
      rotation: 0,
      scale: [1, 1, 1]
    });
    setPolyPoints([]);
    setStartPoint(null);
  };

  const previewPoints = useMemo(() => {
     if (tool === ToolType.DRAW_POLY) {
        if (polyPoints.length === 0 && !currentPoint) return [];
        const pts = [...polyPoints];
        if (currentPoint) pts.push(currentPoint);
        return pts;
     }

     if (startPoint && currentPoint) {
         if (tool === ToolType.DRAW_LINE) {
             const thickness = 0.2;
             const dx = currentPoint.x - startPoint.x;
             const dz = currentPoint.z - startPoint.z;
             const len = Math.sqrt(dx*dx + dz*dz);
             if (len < 0.01) return [startPoint, currentPoint];
             const nx = -dz / len;
             const nz = dx / len;
             const ox = nx * (thickness / 2);
             const oz = nz * (thickness / 2);
             return [
               { x: startPoint.x + ox, y: 0, z: startPoint.z + oz },
               { x: currentPoint.x + ox, y: 0, z: currentPoint.z + oz },
               { x: currentPoint.x - ox, y: 0, z: currentPoint.z - oz },
               { x: startPoint.x - ox, y: 0, z: startPoint.z - oz },
               { x: startPoint.x + ox, y: 0, z: startPoint.z + oz },
             ];
         }
         if (tool === ToolType.DRAW_RECT) {
             return [
                 startPoint,
                 { x: currentPoint.x, y: 0, z: startPoint.z },
                 currentPoint,
                 { x: startPoint.x, y: 0, z: currentPoint.z },
                 startPoint
             ];
         }
         if (tool === ToolType.DRAW_CIRCLE || tool === ToolType.DRAW_ARC) {
             const dist = Math.sqrt(Math.pow(currentPoint.x - startPoint.x, 2) + Math.pow(currentPoint.z - startPoint.z, 2));
             const func = tool === ToolType.DRAW_CIRCLE ? createCirclePoints : createArcPoints;
             const seg = tool === ToolType.DRAW_CIRCLE ? 64 : 32;
             return func(dist, seg).map(p => ({
                 x: p.x + startPoint.x,
                 y: 0,
                 z: p.z + startPoint.z
             }));
         }
     }
     return [];
  }, [tool, startPoint, currentPoint, polyPoints]);

  const drawY = useMemo(() => {
    if (startPoint) return startPoint.y;
    if (polyPoints.length > 0) return polyPoints[0].y;
    if (currentPoint) return currentPoint.y;
    return 0;
  }, [startPoint, polyPoints, currentPoint]);

  return (
    <>
      <mesh 
        name="ground_plane"
        rotation={[-Math.PI / 2, 0, 0]} 
        position={[0, -0.01, 0]} 
        onClick={handleClick}
      >
        <planeGeometry args={[100, 100]} />
        <meshBasicMaterial color="black" transparent opacity={0} />
      </mesh>

      {currentPoint && tool !== ToolType.SELECT && tool !== ToolType.PUSH_PULL && (
        <mesh name="cursor_helper" position={[currentPoint.x, currentPoint.y + 0.05, currentPoint.z]} rotation={[-Math.PI / 2, 0, 0]}>
          <ringGeometry args={[0.1, 0.15, 32]} />
          <meshBasicMaterial color="#ef4444" depthTest={false} />
        </mesh>
      )}

      {tool === ToolType.MEASURE && measureStart && (
        <>
            <Line 
                points={[
                    [measureStart.x, measureStart.y + 0.05, measureStart.z],
                    (() => {
                        const target = measureEnd || currentPoint || measureStart;
                        return [target.x, target.y + 0.05, target.z] as [number, number, number];
                    })()
                ]} 
                color="#facc15" 
                lineWidth={2} 
                dashed 
                dashScale={50}
                depthTest={false}
            />
            {/* ... dots and tooltips ... */}
             <mesh position={[measureStart.x, measureStart.y, measureStart.z]}>
                <sphereGeometry args={[0.08]} />
                <meshBasicMaterial color="#facc15" depthTest={false} />
            </mesh>
            {(measureEnd || currentPoint) && (
                <mesh position={(() => {
                    const p = measureEnd || currentPoint;
                    return p ? [p.x, p.y, p.z] : [0,0,0];
                })()}>
                    <sphereGeometry args={[0.08]} />
                    <meshBasicMaterial color="#facc15" depthTest={false} />
                </mesh>
            )}
             <CursorTooltip 
                position={(() => {
                    const target = measureEnd || currentPoint || measureStart;
                    return [
                        (measureStart.x + target.x) / 2,
                        measureStart.y + 0.5,
                        (measureStart.z + target.z) / 2
                    ] as [number, number, number];
                })()}
                text={(() => {
                    const target = measureEnd || currentPoint || measureStart;
                    const dist = Math.sqrt(
                        Math.pow(target.x - measureStart.x, 2) + 
                        Math.pow(target.z - measureStart.z, 2) +
                        Math.pow(target.y - measureStart.y, 2)
                    );
                    return `距離: ${formatValue(dist)}`;
                })()}
            />
        </>
      )}

      {previewPoints.length > 0 && (startPoint || polyPoints.length > 0) && (
         <PreviewFill points={previewPoints} y={drawY} />
      )}

      {previewPoints.length > 1 && (
        <Line 
           name="preview_helper"
           points={previewPoints.map(p => [p.x, drawY + 0.06, p.z] as [number, number, number])}
           color="#38bdf8"
           lineWidth={2}
           transparent
           opacity={0.8}
        />
      )}
    </>
  );
};

const RenderedShape: React.FC<{ shape: IShape }> = ({ shape }) => {
  const { selectedId, setSelectedId, tool, updateShape, formatValue } = useApp();
  const isSelected = selectedId === shape.id;
  const groupRef = useRef<THREE.Group>(null);

  const threeShape = useMemo(() => {
    if (shape.type === 'dimension') return null;
    return createThreeShape(shape.points);
  }, [shape.points, shape.type]);

  const baseDimensions = useMemo(() => getBaseDimensions(shape.points), [shape.points]);

  const geometry = useMemo(() => {
    if (!threeShape || shape.type === 'dimension') return null;
    return new THREE.ExtrudeGeometry(threeShape, { depth: shape.height, bevelEnabled: false });
  }, [threeShape, shape.height, shape.type]);

  useEffect(() => {
    if (groupRef.current) {
        groupRef.current.position.set(shape.position[0], shape.position[1], shape.position[2]);
        groupRef.current.rotation.set(0, shape.rotation, 0); 
        groupRef.current.scale.set(shape.scale[0], shape.scale[1], shape.scale[2]);
    }
  }, [shape.position, shape.rotation, shape.scale]);

  // Handle updates from TransformControls
  const handleTransformChange = (e: any) => {
      if (!groupRef.current) return;
      // When standard translate/rotate happens in SELECT mode
      updateShape(shape.id, {
        position: [groupRef.current.position.x, groupRef.current.position.y, groupRef.current.position.z],
        rotation: groupRef.current.rotation.y,
        scale: [groupRef.current.scale.x, groupRef.current.scale.y, groupRef.current.scale.z]
      });
  };

  const handleHeightChange = (e: any) => {
    if (e.target.object) {
      const newHeight = e.target.object.position.y;
      if (newHeight > 0.01) {
         updateShape(shape.id, { height: newHeight, type: newHeight > 0.1 ? 'solid' : 'flat' });
      }
    }
  };

  const handleWidthChange = (e: any) => {
      if (!e.target.object) return;
      // We moved a dummy object in X axis. 
      // Current X position relative to origin (center) determines scale.
      const currentX = e.target.object.position.x;
      const baseWidth = baseDimensions.maxX; // since we put anchor at maxX
      // Only support uniform scaling for this side for now or basic stretch
      // Scale = currentX / baseWidth (relative to local center)
      if (baseWidth === 0) return;
      let newScaleX = currentX / baseWidth;
      if (newScaleX < 0.1) newScaleX = 0.1;
      updateShape(shape.id, { scale: [newScaleX, shape.scale[1], shape.scale[2]] });
  };

  const handleDepthChange = (e: any) => {
      if (!e.target.object) return;
      const currentZ = e.target.object.position.z;
      const baseDepth = baseDimensions.maxZ; 
      if (baseDepth === 0) return;
      let newScaleZ = currentZ / baseDepth;
      if (newScaleZ < 0.1) newScaleZ = 0.1;
      updateShape(shape.id, { scale: [shape.scale[0], shape.scale[1], newScaleZ] });
  };

  if (shape.type === 'dimension') {
      const p1 = shape.points[0];
      const p2 = shape.points[1];
      const dist = Math.sqrt(Math.pow(p2.x - p1.x, 2) + Math.pow(p2.z - p1.z, 2) + Math.pow(p2.y - p1.y, 2));
      const midX = (p1.x + p2.x) / 2;
      const midY = (p1.y + p2.y) / 2 + 0.1;
      const midZ = (p1.z + p2.z) / 2;
      return (
        <group 
            ref={groupRef}
            userData={{ isShape: true, id: shape.id }}
            onClick={(e) => {
                if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) {
                    e.stopPropagation();
                    setSelectedId(shape.id);
                }
            }}
        >
            <Line points={[[p1.x, p1.y+0.05, p1.z], [p2.x, p2.y+0.05, p2.z]]} color={isSelected ? HIGHLIGHT_COLOR : shape.color} lineWidth={3} dashed dashScale={10} />
            <mesh position={[p1.x, p1.y+0.05, p1.z]}><sphereGeometry args={[0.06]} /><meshBasicMaterial color={isSelected ? HIGHLIGHT_COLOR : shape.color} /></mesh>
            <mesh position={[p2.x, p2.y+0.05, p2.z]}><sphereGeometry args={[0.06]} /><meshBasicMaterial color={isSelected ? HIGHLIGHT_COLOR : shape.color} /></mesh>
            <Html position={[midX, midY, midZ]} center style={{ pointerEvents: 'none' }}>
                <div className={`text-xs px-2 py-1 rounded whitespace-nowrap backdrop-blur-sm border ${isSelected ? 'bg-blue-600/90 text-white border-blue-400' : 'bg-black/70 text-yellow-400 border-yellow-500/50'}`}>
                    {formatValue(dist)}
                </div>
            </Html>
        </group>
      );
  }

  const { maxX, maxZ, centerX, centerZ } = baseDimensions;

  return (
    <>
      {/* --- Standard Move/Rotate Controls (Only in SELECT mode) --- */}
      {isSelected && tool === ToolType.SELECT && (
        <TransformControls
            object={groupRef}
            mode="translate" // Allows switching to rotate if we added mode switching, but sticking to translate for Select tool base
            showY={true} showX={true} showZ={true}
            onMouseUp={handleTransformChange}
        />
      )}

      {/* --- Push/Pull Resize Controls (Only in PUSH_PULL mode) --- */}
      {isSelected && tool === ToolType.PUSH_PULL && (
        <>
           {/* Height Control (Green Arrow - Top Center) */}
            <TransformControls
                mode="translate"
                position={[shape.position[0], shape.height, shape.position[2]]} 
                showX={false} showZ={false} showY={true}
                translationSnap={0.05}
                onObjectChange={handleHeightChange}
            >
                <mesh>
                   <boxGeometry args={[0.2, 0.2, 0.2]} />
                   <meshBasicMaterial color="#4ade80" depthTest={false} transparent opacity={0.8} />
                </mesh>
                <Html position={[0.4, 0, 0]} center style={{ pointerEvents: 'none' }}>
                    <div className="bg-green-600 text-white text-xs px-1 rounded font-mono shadow-md whitespace-nowrap">H</div>
                </Html>
            </TransformControls>

            {/* Width Control (Red Arrow - Right Edge) */}
            <TransformControls
                mode="translate"
                // Position relative to object center roughly, but we need world coords.
                // We attach to a dummy object at the edge.
                // Note: TransformControls attaches to 'object', or we can put it in the scene and control a dummy.
                // A simpler way with Drei is to position the TransformControl at the handle location.
                position={[
                    shape.position[0] + (maxX * shape.scale[0] * Math.cos(shape.rotation)) - (centerZ * Math.sin(shape.rotation)),
                    shape.position[1] + shape.height / 2,
                    shape.position[2] + (maxX * shape.scale[0] * Math.sin(shape.rotation)) + (centerZ * Math.cos(shape.rotation))
                ]}
                rotation={[0, shape.rotation, 0]}
                showX={true} showY={false} showZ={false}
                onObjectChange={handleWidthChange}
            >
                <mesh>
                   <boxGeometry args={[0.2, 0.2, 0.2]} />
                   <meshBasicMaterial color="#f87171" depthTest={false} transparent opacity={0.8} />
                </mesh>
                <Html position={[0, 0.4, 0]} center style={{ pointerEvents: 'none' }}>
                    <div className="bg-red-500 text-white text-xs px-1 rounded font-mono shadow-md whitespace-nowrap">W</div>
                </Html>
            </TransformControls>

             {/* Depth Control (Blue Arrow - Front Edge) */}
             <TransformControls
                mode="translate"
                position={[
                    shape.position[0] + (centerX * Math.cos(shape.rotation)) - (maxZ * shape.scale[2] * Math.sin(shape.rotation)),
                    shape.position[1] + shape.height / 2,
                    shape.position[2] + (centerX * Math.sin(shape.rotation)) + (maxZ * shape.scale[2] * Math.cos(shape.rotation))
                ]}
                rotation={[0, shape.rotation, 0]}
                showX={false} showY={false} showZ={true}
                onObjectChange={handleDepthChange}
            >
                 <mesh>
                   <boxGeometry args={[0.2, 0.2, 0.2]} />
                   <meshBasicMaterial color="#60a5fa" depthTest={false} transparent opacity={0.8} />
                </mesh>
                <Html position={[0, 0.4, 0]} center style={{ pointerEvents: 'none' }}>
                    <div className="bg-blue-500 text-white text-xs px-1 rounded font-mono shadow-md whitespace-nowrap">D</div>
                </Html>
            </TransformControls>
        </>
      )}

      <group 
        ref={groupRef}
        userData={{ isShape: true, id: shape.id }}
        onClick={(e) => {
          if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) {
            e.stopPropagation();
            setSelectedId(shape.id);
          }
        }}
      >
        <mesh rotation={[-Math.PI / 2, 0, 0]}>
            <primitive object={geometry} attach="geometry" />
            <meshStandardMaterial 
              color={isSelected ? HIGHLIGHT_COLOR : shape.color} 
              transparent={isSelected || shape.type === 'flat'} 
              opacity={shape.type === 'flat' ? 0.6 : (isSelected ? 0.9 : 1)}
              side={THREE.DoubleSide}
            />
            {isSelected && (
              <lineSegments>
                <edgesGeometry args={[geometry]} />
                <lineBasicMaterial color="white" />
              </lineSegments>
            )}
        </mesh>
      </group>
    </>
  );
};

const Viewport: React.FC = () => {
    const { shapes } = useApp();

    return (
        <div className="w-full h-full bg-slate-900">
            <Canvas
                shadows
                camera={{ position: [5, 8, 8], fov: 45 }}
                gl={{ preserveDrawingBuffer: true }}
            >
                <color attach="background" args={['#0f172a']} />

                <OrbitControls makeDefault maxPolarAngle={Math.PI / 2.1} />
                <ambientLight intensity={0.5} />
                <directionalLight position={[10, 20, 10]} intensity={1} castShadow />
                <Environment preset="city" />

                <Grid 
                    infiniteGrid 
                    cellSize={1} 
                    sectionSize={5} 
                    fadeDistance={50} 
                    sectionColor="#475569" 
                    cellColor="#1e293b" 
                />

                <DrawingManager />

                {shapes.map(shape => (
                    <RenderedShape key={shape.id} shape={shape} />
                ))}

                <GizmoHelper alignment="bottom-right" margin={[80, 80]}>
                    <GizmoViewport axisColors={['#ef4444', '#22c55e', '#3b82f6']} labelColor="white" />
                </GizmoHelper>
            </Canvas>
        </div>
    );
};

export default Viewport;

